rows["28:886777973"]="*** 재발전력원***"
rows["28:887419540"]="당신이 아는 모든 것이 사라질 것입니다."
rows["28:888142648"]="야구들은 모든 걸 망치고 있어!"
rows["28:893673559"]="잘 마셨나요?"
rows["28:894409608"]=" ⁇ 이네, 위키켓!"
rows["28:895456000"]="내 주변을 둘러봐!"
rows["28:896071063"]="아이언포지 챔피언의 명단"
rows["28:898765139"]="은빛 여명회는 끝났다!"
rows["28:899826694"]="당신을 위해 희생된 것, 마스터"
rows["28:901784440"]="전기가 불어오고!"
rows["28:901902726"]="이곳의 전망은 정말 대단해요!"
rows["28:902951767"]="내가 왕인 데는, 그만한 이유가 있지!"
rows["28:902993069"]="네 시간이 지금이야"
rows["28:906803690"]="부대 수단을 보내!"
rows["28:914320492"]="일어나라... 네 주인을 지켜라!"
rows["28:917106640"]="더 나은 치료사가 필요해요"
rows["28:91785569"]="수호자 타쿠가 깨어났어!"
rows["28:919022618"]="혼자란 외로운 법이지."
rows["28:922521889"]="나 아직 오우거 왕이다. 크하!"
rows["28:92307082"]="뱀이 우리를 압도했습니다."
rows["28:925164352"]="강하다고... 불멸은 아니지..."
rows["28:92682573"]="너무 귀여워요 이제 죽으세요!"
rows["28:928022114"]="여기서 안정을 찾을 수 없을 거야"
rows["28:929477904"]="왜 날 떠나게 되니?"
rows["28:931940215"]="어딜 가니?"
rows["28:932494890"]="운명을 피할 수 없어!"
rows["28:933830871"]="이건 참을 수 없을 정도가 되고 있어요"
rows["28:935725417"]="이건  ⁇ 돌과 콩커스!"
rows["28:939168930"]="무슨 짓을 하고 있어?"
rows["28:943084400"]="루안 웰드한테 보내줘"
rows["28:943406537"]="이제 복수의 시간이로군요."
rows["28:943861966"]="당신들의 노력은 잘못됐어요!"
rows["28:944462124"]="더 많은 마운트가 필요해요"
rows["28:947042785"]="네놈을 뭉개버리겠다!"
rows["28:948396580"]="결국 실패할 거야"
rows["28:950338696"]="우린 절대 포기하지 않을 거야"
rows["28:952231770"]="분노를 잘 발휘하고 집중하라!"
rows["28:952641216"]="치료용 향신료가 있나요?"
rows["28:955669855"]="이쪽으로!"
rows["28:955770560"]="아니, 아무것도 들리지 않았어"
rows["28:957065323"]="내가 무슨 짓을 한 거지? 왜 내가..."
rows["28:959091558"]="감히 누가 소란을 피우느냐?"
rows["28:959382910"]="네, 네, 네!"
rows["28:961502314"]="더 많은 지연이..."
rows["28:962254027"]="혹시... 날 업어 줄 수 없나요?"
rows["28:964397161"]="난 이제 주인님만을 섬겨요."
rows["28:967240008"]="죽음은 어둠 속에서 기다리고 있습니다!"
rows["28:973114287"]="우리가 어떻게 해야 할까요?"
rows["28:973536936"]="오늘, 난 네 옆에 싸워요"
rows["28:974154743"]="- 내 시체 위에!"
rows["28:977600061"]="오케인 위켓, 여기로 돌아가!"
rows["28:979132818"]="그녀의 은혜로, 나자자르 여주님"
rows["28:980878541"]="트윈클레스, 트윈클레스!"
rows["28:984430809"]="기본 손해 (끝없는) 시작"
rows["28:985808003"]="예, 고위 장로?"
rows["28:989105"]="죽음이 다가온다! 파괴하라!"
rows["28:989109005"]="곧 세상에 종말이 닥치리라."
rows["28:989476501"]="그놈이 얼마나 크고 못생긴지 봐!"
rows["28:9935927"]="어떻게 도와드릴까요?"
rows["28:995566614"]="올라와, 우린 여기서 나가야 돼!"
rows["28:999216665"]="저놈은 뭐하는 거야?"
rows["28:999233893"]="테레잔의 멸망은 보장됐어!"
rows["290:1241162305"]="남은 세 명의 정신을 안전하게 되찾는 것이 중요합니다. 저는 나 혼자 그렇게 할 수 없을 정도로 나이가 많고, 그들의 강점에도 불구하고 아이사와 지 모두 자신의 이상에 대해 단호합니다.$B$B영웅의 모든 자질과 그들이 없는 균형이 있는 사람이야"
rows["290:1321995505"]="난 널 잘 몰라 미안해, 허가된 메카노 스트라이더 딜러로서 내가 내 말을 팔 수 있는 사람은 거미의 친구라고 생각되는 사람들뿐이야"
rows["290:1433449480"]="이 메모를 찾으면 내가 죽거나 하프힐 마켓에서$B$B내가 잠시 직장을 떠나서 도시에서 뜨거운 맥주를 즐기길 바랍니다.$B$B만약 내가 정말로 제 임무에 실패했다면, 제 사랑을 보내주십시오.\010- 쇼"
rows["290:1737712853"]="정말, 나는 당신을 부러워: 호드내 임무는 지휘관의 직무입니다.$B$B분명, 젊은 시절, 저는 노년기를 견딜 수 있는 꿈을 살았습니다. 이제 저는 제 지휘하에 있는 군인들 속에서 승리의 영광과 패배의 쓴 맛을 즐기고 있습니다.\010"
rows["290:1962833003"]="내 시력이 예전처럼 없어서, 까마귀가 내 삶을 축복해줬어$B$B곧 네가 제 자리를 차지할 때가 올 거야 내가 아는 모든 걸 가르쳐줬어"
rows["290:647411604"]="생산을 최대한 늘리지 않으면 호드 이 전쟁에서 패배할 수도 있습니다. 호드 전쟁에서 패하면 우리는 최고로 엉덩이에 빠져나가고 최악의 경우 죽습니다.$B$B전 안 좋아하지만, 위스퍼윈드 그로브에서 들은 좋은 말들은 우리를 구하지 않을 겁니다. 하지만 열심히 일하면 될 수도 있습니다."
rows["291:1337972199"]="안녕, 행운아 숫자 좋아?$b$b여기 모든 전투를 추적하고 난 도전자마다 얼마나 많은 싸움을 승리했는지 알 수 있어$b$b이 싸움에서 승자를 예측하고 돈을 벌면 도움이 될 거야"
rows["291:1633862729"]="이 불행한 잔다라리는 찔려 발자국당했고 얼굴에 공포가 아니라 죽음에도 강한 결단력 있는 표정이 있습니다.$b$b그의 열린 눈은 열렬한 열정으로 불타는 것 같지만, 그들은 하늘을 깜빡이지 않고 쳐다보며."
rows["291:252619094"]="우리가 수집한 마지막 상품은 다음 날 시리투스로 보내질 것 같고, 그렇게 되면 누군가가 와서 Ahn'Qiraj 밖에서 있는 스카라브 데이에  ⁇ 을 울려들어 문들을 열어야 합니다. 그때 우리의 붕대가 유용하게 쓰일 겁니다."
rows["291:27605461"]="하늘 을 뚫고 날아가는 것 보다 정신 을 자유롭게 하는 것 은 없다. 우리 의 큰 부족 중심지 썬더 블러프 에서 그러한 곳 이 있다. 블러드호프 마을 에서 북쪽으로 가는 길 은 그 곳 으로 안내 할 것 이다. 엘리베이터 를 타고 정상 에 올라가면, 더 자세한 방향을 알려 줄 수 있는 블러프워치 중 한 명 과 이야기 해 보십시오."
rows["291:739006446"]="제 수준의 공예가라면 간단한 과정이죠.$B$B동물의 피부와 껍질에서 물건을 만드는 가장 어려운 측면은 이 부분들을 직접 획득하는 것입니다. 만약 여러분이 이 짐승으로부터 원조적인 피부를 가져오면, 저는 육신에서 여러 가지 강력한 물건을 만들 수 있습니다."
rows["291:873359965"]="마을의 장로들은 지혜가 모든 강을 흐르고, 모든 연못에서 수집된다는 것을 가르쳐줬습니다. 이 곳의 물이 무엇을 제공하는지 알기 위해 기다릴 수 없습니다.$b$b마을의 장로들도 한 번도  ⁇ 을 믿지 말아야 한다고 가르쳐줬습니다.$b$b<아시오는 케인-케인에 조심스럽게 시선을 던진다.>"
rows["291:934374192"]=" ⁇ , 어쩌면 이 것일지도 몰라요. 어머, 내가 불구멍을 던지는 동안 푸더릭 두발이 날 때려왔던 것을 얘기했지?"
rows["292:1024698157"]="우리 실수로 날 탓할 수 없어 내가 어디로 가고 있는지도 알 수가 없어$b$b하지만 그건 당신이 날 비난할 수 있다는 뜻일지도 몰라요$b$b잠깐, 난 이 배를 잘 다크할 수 있어... 캡틴이 내리는 명령이어야지!"
rows["292:1115455162"]="<고위검사 페어뱅크스는 그의 톱을 들어 올려 몇 가지 끔찍한 흉터를 드러냈다>$B$B내가 거기 있었기 때문에... 나는 하이 ⁇ 드의 가장 신뢰할 수 있는 조언자였기 때문입니다. 스컬지?"
rows["292:1208052663"]="칠흑으로 덮인 밤이 찾아오면 다시 한 번 까마귀가 어둠 속으로 날아올라 본성을 드러낼 것이다. 그때를 대비하라. 충성을 바치면 까마귀와 함께 비상할 것이고, 그렇지 못한 자들은 날개가 잘려 잊혀진 채 비참하게 땅을 걷게 되리라."
rows["292:1522459099"]="레지온의 전진대군의 전면 공격에 맞서?$B$B아니, 역사가 그 다음의 일을 기록하지 않습니다. 왜냐하면 생존자가 없었기 때문입니다. 분노한 악마들은 오늘날 보이는 유적보다 더 많은 것을 남겼고, 아카데미의 비밀은 아즈하라의 땅 아래 묻혀 있었습니다."
rows["292:23127385"]="저는 사무엘 호크입니다. 아라토르 연맹의 주요 공급자입니다. 아라티 연못에 있습니다. 당신이 우리와 함께 지위를 향상시키면서,"
rows["292:55615645"]="가젯잔 타임즈의 기자가신가요?$B$B<마술자에게 그녀가 기대하는 기자가 아니라는 것을 말해줘>$B$B그럼, 만약 반응제가 필요하다면, 필요한 것을 찾아서, 오래 기다리지 마"
rows["292:579726784"]="피더문 페리에 오신 것을 환영합니다. 피더문 포스트폴트와 잊혀진 해안 사이에 바다에서 잃어버린 사람들을 찾아 여행합니다.$b$b준비해야 한다면, 우리 공급자들과 이야기 해 주세요. 그들은 기꺼이 도와줄 것입니다."
rows["293:1013899047"]="좋은 소식이네요. 이 사이트의 에너지와 유물들에 대한 우리의 연구 결과가 나오기 시작했습니다.$B$B우리는 여기 발견된 모그 기기의 이해가 조금이나마 풀려났고, 더 나은 것은 그들을 우리 편으로 전환하는 방법입니다. 이 구조의 벽들 자체가 내부의 적들의 힘을 약화시키고 소멸시킬 것입니다."
rows["293:1278434393"]="한 번은  ⁇ 알라스의 울창한 숲에서 집을 가졌고 한 번은 가족, 남편, 자녀들을 가졌고 리치 왕 날 눈깜짝할 사이에 빼앗아갔어요$B$B내가 직접적으로 그를 공격할 수 있는 힘이 없어도, 나는 그에게 세 배로 갚을 것이다!"
rows["293:1474372080"]="내가 한 번이나 말했으면 천번이나 했잖아! 나는 그에게 명령도 받지 않는다. 포세이큰의 어느 하나도 받지 않는다!"
rows["293:1479683309"]="미안해, 내가 허가된 메카노 스트라이더 딜러로서, 내가 승마를 팔 수 있는 사람은 거미들 사이에서 우월한 사람이라고 여겨지는 사람들뿐이야."
rows["293:1985512675"]="안녕하세요, 제 이름은 페트라입니다. 오른쪽에 제 코도다가 있습니다. 우리는 마사셜 탐험대에 있습니다.$B$B만약 불꽃이나 불꽃의 원천이 있다면, 가능한 한 숨어서두세요."
rows["293:348377449"]="할머니, 저는 결코 영광이 없었어요. 두로탄은 제 시대보다 오래 전에 죽었지만 그의 영웅성은 제 세계에 모두 알려져 있습니다. 아제로스 이 지역은 듀로타그리고... 잠시 숨을 쉬고, 할머니에게 말할 예정이 있는 걸 생각해봐.\010"
rows["293:486431187"]="안녕하세요$b$b내 이름은 샤이$b$b절벽을 지켜야 한다고$b$b가끔 새끼들이 도전을 하기 때문에, 어른들은 호기심을 하기 때문에 올 때가 있습니다.$b$b내가 그들에게 말하는 걸 말해줘요, 절벽은 슬프고, 정글은 더 슬픈 거야.$b$b로프를 이용해서 내려갈 수도 있지만, 매우 슬픈 곳이라고 생각하세요."
rows["293:635954785"]="의심할 여지 없이 당신은 더 이상 무능한 바보입니다. 어둠의 여신으로부터 그녀의 챔피언에 훈련하도록 보내졌습니다.$B$B<나탄소 서거>$B$B너희들 모두를 조각으로 돌려보내줬어 이번에는 왜 달라지는지 모르겠어$B$B하지만 왜 그런지 묻지 말고 암흑의 여인이 요구하는 대로 해야 합니다."
rows["293:727558268"]="우리가 수집한 음식과 전쟁용품은 실리투스로 향하고 있습니다. 하루도 안 되는 시간 안에 도착할 것입니다. 누군가 제게 말했습니다."
rows["293:903207415"]="내 눈은 나를 속이고요?$B$B사이'클을 찾고 있다면 그는 도각지대 피너클의 서부 부분의 결정들 사이에서 걸어가고 있습니다. 그는 야만적이고 원시적인 존재라고 부르는 것에 대해 바빴다고 보지만, 아무 것도 잘못되지 않은 것처럼 보입니다."
rows["293:949468234"]="이 전쟁 재물이 실리투스 사막에 도착할 때까지 낚시하기 위해 하루밖에 남지 않아서 모든 것이 준비될 것이고,"
rows["294:1130268760"]="알테락에는 두 개의 광산이 있다. 얼라이언스 지역에서 이런데프 광산과 호드 지역에서 콜드투트 광산. 두 광산 모두 미네랄의 풍부한 원천이며, 과거에는 과잉 공급을 저장하는 데 사용되었다.$B$B현재, 이 광산들은 호드, 얼라이언스 및 지역 주민들에 의해 끊임없이 싸워지고 있습니다."
rows["294:1774208278"]="존경하는 살데릴 경, 파티 음식이 좀 부족한 듯합니다. 산들바람 마을에 심부름꾼을 보내서 필요한 물건을 좀 더 배달시켜야겠습니다. 특히 훈제 삼겹살로 싼 한입 요리가 좋겠는데요. 뭐라고 부르는 음식이었죠?"
rows["294:1849776941"]="이제 전쟁이 곧 일어날 것입니다. 남은 것은 모든 상품과 무기를 실리투스 센라리온 포크로 보내야 합니다. 그리고 그것은 $2113w일 이내에 이루어질 것입니다."
rows["294:2044713668"]="나이트 엘프 군대는 운고로 분화구를 통해 타나리스 사막의 경계까지 후퇴했습니다. 그런데 운고로에 있는 무언가가 퀴라지의 침범을 막고 있었습니다. 이 글자가 무슨 뜻인지 정확하게 이해할 수는 없지만 '신들의 땅'을 말하는 것 같아요. '그들은 신들의 땅을 침범할 수 없었다'라고 적혀 있네요."
rows["294:271005640"]="사우로크는 모든 기회를 이용해서 약탈을 하고, 경비원들이 공용이 없어서 우리의 물품을 밤새 공격하고 있습니다.$B$B그들은 그들이 가지고 갈 수 있는 모든 것을 가져가 그들의 쉼터로 돌아갑니다.$B$B공예품과 색소 제조는 그들이 확실히 할 것 중 일부입니다."
rows["294:487030231"]="제디스 바로프의 저널은 죽은 자들에 대한 거론과 험담으로 가득 차 있습니다. 책의 마지막에 felth bag을 만드는 데의  ⁇ 질 패턴이 보이는 것 같습니다. 이 가방은 마녀들이 영혼 조각을 저장하는 데 사용합니다. 당신은 당신의 저널에 패턴을 복사하고 싶습니까?"
rows["294:494192783"]="얘야... 언젠가 네가 파멸의 인도자를 휘두를 날이 올 게다. 검을 들고, 너는 온 세상을 누비며 정의를 수호하겠지. 난 믿어 의심치 않는단다. 그날이 오면, 너는 우리 모두의 자랑이 되고 로데론은 내 아들 덕에 더 살기 좋은 땅이 될 테지. 하지만 아들아, 아직은 때가 아니다."
rows["295:1143279203"]="휴식을 취할 때, 얼라이언스는 우리 뒤에 있습니다. 우리는 모두 우리의 수집'을 완료했습니다. 그리고 마지막  ⁇ 은 우리가 말하는 것 '에 가. 그들은 그들의 아이언포지에서 끝낼 때, 우리는 생각'이 모든 것들을 Silithus 이동'에 대해. '그때까지, 앉아 가만히 있고 어쩌면 약간의 낚시 할 수 있습니다.'"
rows["295:1540743744"]="강해지세요. 카엘타스는 우리를 배신하고 우리가 알고 있는 것은 변동하고 있지만, 실망하지 마세요. 우리는 항상 그랬듯이 견뎌낼 것입니다. 아르타스는 우리의 땅을 휩쓸었을 때 우리의 정신을 꺾지 않았고 카엘타스는 그렇게 하지 않을 것입니다."
rows["295:1660232611"]="섬에 돌아다니는 손상된 경호를 본 적 있나요? 그들의 행동을 통제하는 결정에 몇 가지 변경이 가능해지면$B$B태양의 도달 성당은 곧 우리의 것입니다. $3244w 이 목표를 달성하는 비율이"
rows["295:1720724327"]="저는 제 정체성에 대해 완전히 솔직하지 않은 것에 대해 사과해야 합니다. 저는 여러분께 믿을 수 있다는 확신을 가져야 했습니다.$B$B당신은 그 사람들 중 한 명으로 증명되었습니다. 정직하고 명예로운 사람이죠."
rows["295:1738481855"]="누가 이 영역에서 가장 인기 있는 영웅인가?$B$B ⁇ : $2200w$B카에른: $2201w$B실바나스: $2202w$B전체 호드: $2207w$B$B변수: $2203w$B마그니: $2204w$B타이란데: $2205w$B전체 얼라이언스: $2206w$B$B투표를 하고 싶다면 선물 모집을 제출하세요!"
rows["295:2010260989"]="모든 수집이 완료되고 완성된 제품은 실리투스로 배송되고 있습니다. 마치고 있는 것처럼 보입니다. 모든 것이 거기에 도착하기까지 $2113w 며칠이 채 되지 않습니다. 그 후에 우리는 단지 누군가가  ⁇ 을 울리고 아앙키라지로 문들을 열어야 합니다. 그러면 진짜 재미가 시작됩니다."
rows["295:236889418"]="어서 오게, 용사들이여! 은빛십자군의 부름에 담대히 응한 모두를 환영하네! 바로 이곳, 십자군 원형경기장에서 제군들은 엄청난 도전에 마주칠 걸세. 혹독한 원형경기장에서 살아남는 자는 은빛십자군의 일원이 되어 얼음왕관 성채로 진군해 나갈 걸세."
rows["295:348562157"]="불행히도 블러드하프 마을에서는  ⁇ 을 가르치는 사람이 없지만 썬더 블러프에서 트레이너를 찾을 수 있습니다. 마을 밖으로 북쪽으로 가는 길을 따라 엘리베이터에 도착하기 전까지는 엘리베이터로 이동합니다. 엘리베이터 하나를 타고 승강장 꼭대기에 올라가서 그 곳의 블러프워치 중 한 명을 안내해 주세요."
rows["295:421005488"]="훌륭한 요리사가 되고 싶다면, 구시의 돼지와 휘슬 타버너에 가서 스티븐 라이백과 이야기해봐요. 그 사람은 다른 누구도 모르는 肋骨을 요리하는 법을 알고 있습니다.\010저한테서 유명한 肋骨을 먹기 싫었어"
rows["295:482550645"]="환영합니다! Yebb Neblegear의 Darkmoon Zoo Bizarre - 살아있는 전설과 신화적 이상성의 발견! 방문을 즐기십시오, 친구!$B$B하지만 만지는 것에 주의하라 이 전시품에는 끔찍한 동물들이 있고"
rows["295:689109438"]="포세이큰은 호드와 얼라이언스의 양쪽에서 전염병을 치료하는 데에 대해 다루고 있지만, 우리는 우리 도시를 포위하는 스컬지 네크로폴리를 처리하기로 약속했습니다.$B$B집중된 빛 에너지를 사용하여 우리는 리치 왕의 구조에 반격하여 운 좋게 파괴할 수 있습니다."
rows["295:73957733"]="네. 너무 많은 주문이 왜곡하고 뒤집어 놓았어요. 우리가 특히 당신들이 포털로 만든 거세기는 너무 많았습니다! 불타는 군단를 다시 그들의 불쾌한 영역으로 보내던 마법은 이제 우물에서 작동합니다. 그것은 스스로를 삼키고 그 주변을 가지고 있습니다. 매력적인, 그렇지 않습니까?"
rows["295:790411391"]="내가 너라면 눈을 뜨고 귀를 기울일 거야 너 때문에 카자로 산과 잃어버린 섬 화산이 폭발했다는 소문이 퍼져나가고 있어$B$B미친 짓은 알아요 하지만 사람들은 뭐든지 거론하고 영웅들을 파괴하는 걸 좋아하죠"
rows["295:857716284"]="파란색 용들이 여기 있지 않지만 마일고스의 추종자들은 여기 있지요. 왜인지 모르겠지만, 제가 여러분에게 이렇게 말할 수 있습니다. 파란색 용들이 어디에 있든, 미묘한 마술을 발견할 것으로 기대합니다."
rows["296:1125900237"]="북쪽 항구 에서, 당신은 루테라랑 마을 과 다르나서스까지 운반 될 선박 에 탑승 할 수 있습니다. 남쪽 항구 에서 대해 를 건너 스톰윈드 항구 로 가는 통로를 찾을 수 있습니다. 서쪽 항구 에서 항구 끝 에서, 에스도다르 근처 에 있는 아저레미스트 섬 으로 이어집니다. 안전 한 여행 을 바랍니다!"
rows["296:1266051271"]="내 친구, 넌 나보다 더 실력 있는 사람이야. 왜 내 오래된 친구 로트거 스톤바드를 찾아내지 않는가? 그는 제이나의 군대에 합류하기 위해 갔을 때 아이언포지에 머물렀어요. 나는 그가 당신에게 뭔가를 가르쳐 줄 수 있을 것이라고 확신합니다. 또는 적어도 아는 사람을 알고 있습니다. 그가 여전히 주변에 있다면, 나는 그가 위대한 포지에서있을 것이라고 확신합니다."
rows["296:152239146"]="제 이름은 J.D. 그리고 제가 어떻게 여기 왔는지 잘 알려주지 못하지만 이 캠프가 이제 내 고향이라는 걸 알 수 있습니다!$B$B크레이터 곳곳에서 발견되는 이상한 크리스탈을 연구하는 시간을 보냈습니다."
rows["296:1549359436"]="나 봐 농민, 내 몸에는 머리부터 발끝까지 유물이 있어 아제로스 그 누구도 몰랐어요$B$B이제 자기 자신을 봐$B$B빨리, 날 돌아 봐$B$B이 말은 별으로 만들어졌습니다.$B$B정신적으로 결핍된 오크에게 어떤 무리한 임무가 준비됐을까요?"
rows["296:1603291729"]="저는 오래전부터 선리버들과 대결할 기회를 기다렸지만, 시내에서 그들을 제거하라고 남편에게 요청했으나, 그는 키린 토르의 중립성에 너무 굳게 믿었습니다.$b$b그는 지혜로운 사람이었지만 단시경이었습니다. 이것은 항상 키린 토르의 운명이었습니다. 얼라이언스에 봉사하는 것입니다."
rows["296:1767588200"]="왜 신경쓰는 건데? 그들은 내가 어디 있는지 전혀 알 수 없죠. 그들은 이미 발견된 유물에 아무런 해를 끼치지 않을 겁니다.$B$B어쨌든 악과 파괴의 재미있는 편리한 점은 결국 악적으로 서로를 파괴하는 경향이 있다는 것입니다."
rows["296:467817531"]=" ⁇ 리 가게에 오신 걸 환영합니다. 컷을 받으러 오세요? 색칠을 받으러 오세요?$B$B얼굴 머리카락을 잘라내며 피어징을 할 수 있고, 손톱과 뿔을 재구조할 수 있고, 심지어 죽은 자들의 특징을 수정할 수도 있습니다!$B$B앉으면 곧바로 일을 시작해줄게"
rows["296:514108597"]="이 죽음의 기사들은 정말 영광이 없습니다. 첫째, 그들은 나의 가장 위대한 무기와 갑옷을 가져가요, 조심스럽게 제작되어, 리치 왕의 축복으로 만들어졌습니다. 그리고 그들은 누가 알 수 있는 곳으로 떠돌고 돌아와서"
rows["297:1225237917"]="켈트루자드는 직원을 개혁하려는 노력에 상당한 노력을 기울였습니다. 이 조각은 한때 이 세계에 흩어져 있었습니다. 칼림도어에서 남해까지. 나는 그 중 20 조각을 한 번에 가지고있었습니다. 켈트루자드의 하자가 내게서 훔쳐갈 때까지. 그래서 나는 여기 있습니다."
rows["297:1870872283"]="와일드햄어의 친구 환영합니다!$B$B키르트헤븐은 우리 민족의 영적 중심지이고 다양한 부족들이 평화롭게 모여들 수 있는 유일한 장소입니다.$B$B여기 우리는 죽은 영웅들을 기어두고, 그 지리폰을 기어두고,"
rows["297:1872604700"]="- 그냥 $2113w 이 모든 전쟁 재물이 실리투스 사막에 도착하기 전까지 더 많은 날들이 남아 있습니다. 그리고 그들은 모든 것을 준비하고 있을 것입니다."
rows["297:1997036375"]="브리즈트!$B$B보안 레벨 치 터미널인 매트릭스 펀코그래프 3005 C 스트로크에 오신 것을 환영합니다.$B$B파란색 펀치 카드 확인됐습니다\01001000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001"
rows["297:2007415553"]="보시다시피 저 저 광장에서 도망가는 거북이 몇 명이 있었는데 거미에 대해 얘기하고 새로운 고객들이 있었는데"
rows["297:347622428"]="크레나, 내 능력에 의심할 거야. 우리 엘리트 전사들은 얼라이언스와 그들의 함수 동맹군들을 마주치거나 트롤들 사이에서 파괴를 일으키지만,$B$B어쩌면 우리가 함께 노력한다면, 우리는 둘 다 정복자의 눈에 자신을 증명할 수 있을지도 모릅니다."
rows["297:490164462"]=" ⁇ 림은 사회적 자질이 부족해 연습생들과 얘기하지만 대부분 자기 자신만 이야기하며 다른 사람들을 속이는 경향이 있습니다.$B$B제 정신이 마법을 공부할 수 없다고 말했어요.\010"
rows["297:795765322"]="아뇨, 원숭이 왕은 타지 안 돼!$b$b이고이  ⁇ 은 아버지로부터 지팡이를 받았고, 그의 아버지는 그보다 먼저, 그리고 그의 아버지는 그보다 앞서$b$b원숭이 왕은 오래전부터 내 가족에게 막대를 주었고$b$b그놈은 그렇게 오래 살지 못해!"
rows["297:84018804"]="전에도 말했잖소. 데솔름에 병력을 집중해야만 만족스러운 성과를 얻을 수 있다고... 다른 목표들은 어떻게든 해낼 수 있소. 부인이 순찰대장 헬리오스에게 그림자소나무 트롤과 싸움을 중지하고 스컬지에만 신경을 쓰라고 말씀해 주시오."
rows["298:1709663880"]="실버문 라이더들은 균형과 정확성에 믿고 공격과 방어를 능숙하게 혼합합니다.$B$B하지만 그들은 종종 당신에게서 범위를 얻기 위해 자신의 무기를 열어줍니다.$B$B그들이 똑같은 일을 하기 전에  ⁇ 을  ⁇ 어  ⁇ 을  ⁇ 고, 더 많은 충격을 위해 돌아다니면서 쉴드 브레이크를 해내라."
rows["298:1808283934"]="곤메레건 라이더들은 균형과 정확성에 믿고 공격과 방어를 능숙하게 혼합합니다.$B$B하지만 그들은 종종 당신에게서 범위를 얻기 위해 자신의 무기를 열어줍니다.$B$B그들이 똑같은 일을 하기 전에  ⁇ 을  ⁇ 어  ⁇ 을  ⁇ 고, 더 많은 충격을 위해 돌아다니면서 쉴드 브레이크를 해내라."
rows["298:2088686913"]="이 방은 전통적인 모고 디자인과 여러 가지 면에서 다른 독특한 건축물입니다. 이 방은 일종의 장치처럼 보이지만, 제 메모에는 그 목적에 대해 아무것도 보이지 않습니다.  \010$b우리가 이 장치의 목적에 대해 알아낼 수 있는 유일한 방법은 그것을 활성화하고 관찰하는 것입니다.\010$b무슨 일이 일어날 수 있어?"
rows["298:239846950"]="한때 밤의 엘프들의 위대한 도시였던 하이보른은 한때 그곳에서 통치하고 있었고, 크고 강력한 미묘한 마술을 행하고 있었습니다. 그들은 이제 저주받고, 땅을 괴롭히고 있습니다. 그리고 그들의 파괴된 도시는 스피텔라시 나가들에 의해 희생되었습니다."
rows["298:408207539"]="저같은 사람이 그 나무를 벌이는 이끼에게 잡히면, 당신은 정말 용감해 여기 오게 될 겁니다.\010하프스를 방해하고 내 연쇄를 깨면 내가 네 옆에 싸워줄게\010폭풍에 적을 몰아넣는 능력은 하프스의 노력이 망칠 것입니다"
rows["298:636651562"]="채굴 직업은 생산 직업에서 사용되는 원료를 얻을 수 있습니다.\010당신은 수집으로 관련 생산 직업을 지원하거나, 단순히 경매장에서 원료를 판매할 수 있습니다."
rows["298:760606949"]="오늘은 매우 생산적인 날입니다!$b$b이 방은 실제로 고대 기원이며, 고장된 것처럼 보이는 멋진 메커니즘을 갖추고 있습니다.$b$b내일 더 자세히 조사해볼게요$b$b이 발견은 확실히 스노츠를 저를 주목하도록 강요할 것입니다!$b$b어떻게 이런 일이 일어나서 승진을 거절할 수 있었을까요?"
rows["298:844398002"]="지구 어머니 의 열매 를 사용 하여 우리 의 영원 한 투쟁 에 도움 을 주기 위한 약 을 만들어내는 것 은 영광 스러운 노력 이다. 이 점 을 배우기 위해 당신은 북쪽 으로 우리 의 위대한 고향 썬더 블러프 으로 여행 해야 한다."
rows["299:1317872171"]="우리는 호드가 원하는 만큼의 얇은 늑대 스테이크를 가지고 있다고 보이죠. 그들은 우리가 여기있는 것을 포장하고 시리투스에있는 센라리오니온 홀드에 배송하도록 준비하라고 말했다. 하지만 다른 몇몇 사람들은 여전히 그들이 관리하는 것을 수집하고 있을 것 같습니다. 그들 중 하나를 버그로 이동하십시오."
rows["299:1492428330"]="우리가 수집한 음식과 전쟁 재물은 모두 실리투스로 향하고 있습니다. $2113w일 이내에 도착해야 합니다. 누군가가 제게 말했습니다."
rows["299:1760334934"]="이스파르가 숨쉬고 있습니다.$B$B나무집은 집처럼 살지 못하지만 세텍홀보다 훨씬 더 좋아졌어요$B$B스 ⁇ 트라트에서 편안한 상태였지만, 동생이 없는 스켓티스에서 고향으로 돌아가지 못해"
rows["299:1871382406"]="놀라운 물건들이죠?$B$B제가 더 인상 깊게 느끼는 것은 그 크기나 그 이야기들이 아닐까 모르겠습니다. 연구하고 배울 것이 많고, 우리가 만들어낼 수 있는 연결은...$B$B많은 인종들이 밤 엘프와 같은 유산을 가지고 있다는 소문이 전해지고 있다는 것을 알고 계셨습니까?"
rows["299:1922616547"]="우리 가족은 반도아 대륙을 떠나 방황하는 섬의 뒷편에서 세계를 탐험했습니다.$b$b하지만 난 파다리아에 다른 스톰스타우트가 있다는 걸 알아냈어. 오래전 잃어버린 가족이야. 그들은 어떻게 생겼나? 그들은 아직도 내가 하는 것처럼  ⁇ 나요?"
rows["299:2134901081"]="불의 주인과 그의 형제들은 한때 이 모든 세상을 지배하고 있었습니다. 이 세상에는 필사적 존재가 있었습니다. 그는 옛 신들의 종으로서 이 행성의 지배를 위해 타이탄들과 싸웠습니다."
rows["299:300021988"]="마모 킹이 거기 있었는데 마지막 때 이 망치가 맞았어요. 눈물이 눈앞에 들어왔고, 조화도 느껴졌습니다. 하지만 더 이상 기름은 만들어지지 않았습니다. 모그가 그들의 침략과 함께 왔기 때문입니다. 당신이 가진 것을 사용하십시오."
rows["299:684663159"]=" ⁇ 티, 그건 내가 오래전에 들어본 말이야!$B$B할아버지는 일어나서 어디를 가려고 하지 않을 때 이렇게 부르곤 했어요. 그는 목을 잡고 \"나비  ⁇ 처럼\" 날 들어올리곤 했습니다.$B$B이 농작물은 수직으로 가는 데 도움이 필요해요"
rows["299:809477046"]="당신의 jormungar은 눈이 아래 잠겨있을 때만 움직일 수 있지만 잠겨있을 때 공격할 수 없습니다. 당신의 jormungar이 등장하면 강력한 산 공격을 사용하여 철 콜로스의 갑옷을 착용 할 수 있습니다. 철 콜로스의 가장 파괴적인 공격에서 탈출하기 위해 잠수할 준비가 되십시오."
