rows["29:872770475"]="%s Vol'jin 목에 칼을 찔러"
rows["29:878281005"]="누가 감히 우리 주인님을 귀찮게 하는 거냐?"
rows["29:879882085"]="난 그 모든 거꾸로 갈 수 있어"
rows["29:881147028"]="비는 깨졌어 물러나라"
rows["29:882282639"]="대피하라! 포를 잡아라!"
