rows["29:89994129"]="고통은 이제 막 시작됐어"
rows["29:900135585"]="그냥 내 야크를 되찾고 싶었어요"
rows["29:901486090"]="그럼 여기서 뭐하는 거야?"
rows["29:901595439"]="그래, 공자님, 준비됐습니다."
rows["29:904212751"]="준비됐어요, 코라스트라사 부인"
rows["29:906555026"]=" ⁇ 을 통제할 수 없어!"
rows["29:9069174"]="어떻게 도와드릴까요?"
rows["29:908863527"]="오키도키, R 준비 됐어!"
rows["29:911576753"]="한 발자국은 무슨, 백만 스물 하고도 두 발자국이겠죠!"
rows["29:91329042"]="오론,  ⁇ 이 전화해!"
