rows["29:916573174"]="우리의 요새가 준비되어 있습니다."
rows["29:919917820"]="잔과 술통을 전부 비워라!"
rows["29:921167429"]="실패의 대가 바로 그런 겁니다."
rows["29:921396174"]="지금 기분이 훨씬 좋아졌어요..."
rows["29:922908679"]="계획은 예정대로... 진행된다."
rows["29:923806599"]="내 영혼을 풀어줘,  ⁇ !"
rows["29:924805817"]="넌 여기서 뭐하는 거야?"
rows["29:925255384"]="자루트가 어디로 갔어요?"
rows["29:926624794"]="그린스톤 마을에 줄을 서"
rows["29:929736551"]="여기 뭐가 있는지 보자"
rows["29:93096822"]="린우보쇼, 수리 필요해"
rows["29:935702553"]="지나 무드클라우가 사는 곳은 어디죠?"
rows["29:939309292"]="핫도그였어?"
rows["29:944278202"]="이제 끝났어! 넌 끝장이라고!"
rows["29:952456273"]="호드는 농장을 점령했습니다!"
rows["29:95655438"]="불타라, 비천한 것들!"
rows["29:964607070"]=" ⁇ 이 안 돼!"
rows["29:967689555"]="그 척도는...  ⁇ 어..."
