rows["29:97792308"]="너에게 주어진 시간은 끝났다."
rows["29:978273938"]="이제 그만해"
rows["29:982842673"]="이 아만을 이곳으로 부른 자가 누구인가?"
rows["29:985012171"]="이 돈 받는게 좋아"
rows["29:985691984"]="다로우골! 이제 끝장이다!"
rows["29:98702270"]="아직도 버텨? 오래가진 못할 게다."
rows["29:988504861"]="고마워요, 정말 빚진답니다."
rows["29:993331855"]="내 투표를 더 잘 받았어"
rows["29:994577839"]="굴에서 나오세요 겁쟁이들아!"
