rows["29:999151874"]="이건  ⁇ 고의 흔적이 아냐"
rows["300:1011786536"]="우리 훈련장에서 반려동물 전투가 있는 것 같아요. 구름 뱀은 거의 모든 일을 할 수 있도록 만들어졌습니다. 다른 반려동물을 싸우는 것도 포함합니다. 새끼를 찾는 열쇠는 어른과 우정을 쌓는 것입니다. 일단 당신이 명령에 의해 높이 평가되면, 당신은 그들을 나무집에 흩어져 발견할 것입니다."
rows["300:108830881"]="이 곳에는 많은 것을 배울 수 있고 발견할 수 있습니다. 저는 여기 모든 발견으로 책과 책을 채울 것입니다.$b$b하지만 너무 많은 정보인데 어떻게 누가 이 모든 걸 읽어낼 수 있을지 모르겠어요"
rows["300:1260867772"]="마지막 전쟁에서 타우렌은 싸웠고 샤만은 이 세상을 방어하기 위해 스컬지 침략으로 인해 많은 사람들이 목숨을 잃었습니다. 다른 방법으로는 많은 사람들이 찢어졌습니다. 그들의 신체 부위가 저주받은 성곽에서 불쾌한 실험을 위해 사용되었습니다."
rows["300:1565928471"]="달라란의 멸망 후, 저는 키린 토르에서 떠나고, 몇 년 동안 아티시를 지켜봤지만, 키린 토르의 내 목적이 한 번이나 빼앗겨갔어요."
rows["300:1814065101"]="거칠고 난 잡초들은 끊임없이 괴롭힘이고, 땅에  ⁇ 어 올라서$B$B그 토지를 재배하기 전에, 풀을 뽑아야 합니다.$B$B할아버지의 말로는 \"마초보다 더 화려해야 해!\""
rows["300:191947074"]="운명의 순간이군요! 다른 쪽에서 새로운 시작이 기다리고 있습니다. 새로운 적을 학살합니다. 당신은 그것을 느낄 수 있습니다, 그렇지 않습니까? 피 갈증 증가? 블랙핸드! 그의 명령을 따르십시오. 그리고 당신은 당신의 권리와 같이 이 새로운 세계를 통치 할 것입니다. 그것은 포털의 다른 쪽에 당신의 세계입니다. 그것을 가져가십시오."
rows["300:2022141393"]="당신이 수집한 오케이드들을 이용해 광신 맥주 제조업자의 계곡에 있는 호수를 깨끗하게 해낼 수 있습니다.$b$b제 친구 지안은 내 맥주 몇 개를 만드는 데 도움이 된 물 스프라이트입니다. 그리고 적절한 수밀도를 얻는 데 매우 유용합니다. 그는 이 허브를 가장 잘 배포하는 방법을 알고 있습니다."
rows["300:23540447"]="제 동료들과 저는 우리가 아는 가장 위대한, 가장 이기적인 사람을 기리기 위해 우리 자신을 로타르의 아들이라고 불렀습니다.$B$B이 멸망된 세상이 우리 주위에 무너지면서 우리는 더 많은 피해를 방지하기 위해 어두운 포털을 깨뜨렸습니다 아제로스."
rows["300:501038669"]="놀라운 것! 여기서는 제가 본 적이 없는 구절들이 있습니다. 이 구절을 찾아내기에는 꽤 오랜 시간이 걸렸을 겁니다. 이런 책들을 더 찾아내면, 저는 즉시 알려드리고 싶습니다.\010제 키린 토르 친숙자 중 한 명을 데려가세요"
rows["300:75044619"]="이 곳은... 저주받은 곳이야$B$B난 겨우 탈출을 해냈고, 또 터널을 통과할 수 없어$B$B내 형제와 자매들은 운이 좋지 못했지만, 그 안에 갇혀있어서,$B$B제발, 도와줘요"
rows["300:782506948"]="제 계획은 이 지하 물들을 바로 에메랄드 드림과 연결하는 것이었습니다. 제 충실한 제자들과 함께 저는 울음소리 동굴의 깊숙한 곳에 여행했습니다.$B$B그 곳에서 모든 것이 잘못되었습니다."
rows["301:1014196245"]="사고 이후 일어난 모든 일은 미묘한 것 같아서$B$B이제, 제 현실은 이 섬에 제한되어 있습니다. 이 섬의 돌연변이 생물들과,"
rows["301:1162358466"]="직업 트레이너를 찾고 있나요?$B$B젠 마스터 트레이너들은 파다리아 전역에서 찾을 수 있습니다.$B$B파다리아에서 찾고 있는 사람을 찾을 수 없다면, 고향 도시에서도 직업 마스터를 찾아볼 수 있습니다. 그들은 또한 당신의 공예에 대한 기술을 향상시킬 수 있어야 합니다."
rows["301:1908349122"]="최근에는 암흑 철자들도 더 자주 표면 세계에 나타나고 있습니다. 방탄소년도에서 요새들이 건설되고 있습니다. 고대 유래를 찾기 위해 울다만 깊은 곳으로 대규모 탐사군이 파견되었습니다. 그들은 심지어 우리 고향을 침공하여 호수 근처에 있는 우리의  ⁇ 에 공격했습니다."
rows["301:2045683620"]="먼저 소개합니다. 저는 아르치마지 바르고트입니다. 드레너로 첫 번째 키린 토 원정 탐사의 지도자입니다. 우리는 얼라이언스 세력을 함께 암흑 포털을 통해, 그리고 이제 Farahlon에 기하촌 - Kirin'Var 마을 - 을 설치했습니다."
rows["301:406338977"]="사실, 이 물건은 결국 파괴되었고, 죽음의 날개는 나머지 네 가지의 결합되고 새롭게 된 힘으로 거의 살해되었다. 죽음의 날개는 현재 어디에 있는지 알 수 없습니다. 그러나 우리가 알고 있는 것은 그의 후손 중 한 사람이 네파리안이 이 성곽을 통치하고 그의 아버지가 멈췄던 곳에서 계속하기를 원한다."
rows["301:552420747"]="저같은 사람이 그 나무를 벌이는 이끼에게 잡히면, 당신은 정말 용감해 여기 오게 될 겁니다.\010하프스를 방해하고 내 연쇄를 깨면 내가 네 옆에 싸워줄게\010적의 몸을 일시적으로 마비시킬 수 있는 나의 능력은 해프스의 악성 공격으로부터 쉬게 해 줄 것이다."
rows["301:724212598"]="아쉽게도... 저는 현재 당신의 운명을 줄 수 없다고 죄송합니다. 최근 제 운명을 받았기 때문에.$B$B운명을 처음 받은 날부터 몇 시간 후에 내게 돌아와 운명의 힘들이 제대로 재계급되어서"
rows["301:813411713"]="이 두 부분을 결합시키는 마법에 대한 지식이 없었을 때, 비레톤그 부왕은 왕자줄을 사용할 수 없었습니다. 그러나 이제 비레톤그 부패의 저주에서 해방되어,"
rows["301:835620661"]="이중 전문화는 두 개의 활성 클래스 전문, 재능 및 글리프 세트를 유지하고 쉽게 전환 할 수 있습니다.\010또한 각 세트마다 별도의 글리프 패널과 액션 바를 갖게 될 것입니다.\010전투에서 두 세트를 전환하는 것은 불가능하며, 사용 가능한 자원을 소비할 것입니다."
rows["301:836814752"]="-  ⁇ $b$b<카흐가 생각을 하게 될 때까지 인내심을 가지고 기다려야 하고, 그가 말을 할 때까지 더 기다려라>$b$b카흐카는 많은 조카들을 가지고 있습니다. 그들은 모두 자신의 이름을 얻었습니다.$b$b아직 이름을 알 수 없는 사람에게 집을 짓는 것...$b$b리코는 너무  ⁇ 고 있군, 한 번이라도 걸어서도 잘할 수 있어"
rows["301:9048849"]="죄송합니다, 친구, 우리는 Brill에서 그런 것을 가지고 있지 않습니다. 당신은 그것을 위해 언더시티로 가야 합니다. 언더시티는 Brill 남쪽에서 로데론의 유적 아래 있습니다. 유적의 뒤에서 엘리베이터를 내려가 다음 언더시티 경호자 한 명에게 더 나아가기 위해 이야기하십시오."
rows["302:1381625616"]="새로운 신병들에게 가르쳐주지 않나요?$B$B나아루는 이 기술을 이용해 항해 중에도 배를 가동했습니다. 어떤 사람들은 이 기술을 육지에서 사용하는 것이 안전하지 않을 수도 있다고 말했습니다. 그들은 즉시 침묵했습니다."
rows["302:1386183736"]="스톰퍼 크레그, 다 가드, 캡틴 크롬크루시, 다 옵저버 등 모든 보스 하인들 모두 새 보스를 추모합니다. 만약 하인들을 죽이면 그 하인들은 추모를 할 수 없습니다. 당신이 살아 남긴 모든 사람은 더 많은 추모를 줄 것입니다. 그들 모두를 살아 남게 하려면 큰 추모를 얻을 것입니다.$B$B- 그래!"
rows["302:155445825"]="이 기기는 '데시윙'과 만난 후 완전히 개조 되었습니다! 현재 우리는 고정형 비행기와 회전형 항공기, 그리고 18 인치의 평탄도형 해안 폭격 공기의 배터리를 모두 가지고 있습니다.$b$b호드은 육지나 바다나 공중에서 숨길 수 없습니다."
rows["302:198245812"]="아르헨트 십자군 기사들은 균형과 정확성에 믿고 공격과 방어를 능숙하게 혼합합니다.$B$B하지만 그들은 종종 당신에게서 범위를 얻기 위해 자신의 무기를 열어줍니다.$B$B그들이 똑같은 일을 하기 전에  ⁇ 을  ⁇ 어  ⁇ 을  ⁇ 고, 더 많은 충격을 위해 돌아다니면서 쉴드 브레이크를 해내라."
rows["302:2108195940"]="추적자들은 모두 나가서 범죄자인 학살자 마티스를 찾도록 한다. 내가 아르거스의 손의 믿을 만한 요원에게 신호용 권총을 주었다. 추적자 중 누구라도 그 신호를 보면 그 요원이 마티스를 찾았으며 지원이 필요하다는 뜻으로 알도록 하라. 그리고 추적자들은 마티스를 산 채로 데려와야 한다는 것을 잊지 말도록."
rows["302:23774928"]="시간의 동굴이 필멸의 존재에게 항상 열려 있는지 아닌지는 우리도 모릅니다. 사실 영생을 누리는 시간의 지배자께서 자신의 판단에 따라 우리의 시간의 길을 변화시키시기에 뭐라 말할 수가 없군요. 당신이 지금 보고 있는 것은 내일이 되면 존재하지 않을지도 모른답니다. 당신이 어제로 되돌아가 정신을 차리게 되어 이곳에 대한 기억이 전혀 남아 있지 않을 수도 있습니다."
rows["302:244276504"]="네 일, 정말 놀라운 일을 해낼 수 있는 말이지 내가 네가 가르칠 괴물을 찾아라라고 제안했지 아무도 말하지 마"
rows["302:702736203"]="전설 은 오늘날 Plaguelands 이라고 불리는 곳 에서 극심 한 갈등 이 있는 곳 에서 깨끗 하고 거룩 한 샘 이 땅 에서 터질 수 있다고 주장 한다. 그 샘 이 나오는 물 은 공예 들 과 일반 인 들 이 모두 '유공 들 의 피'라고 명명 해 왔다. 스컬지에 대한 전쟁 에서 쓰러진 사람 들 을 기리기 위해 그렇게 하였다."
rows["303:1119244185"]="델사마르에 오신 것을 환영합니다. 롯 모단에서 고향이 멀어지는 곳입니다.$B$B테일사마르는 좋은 곳이지만, 의무에 부름을 받는 사람들을 위한 맥주와 소금 고기 전부는 아닙니다. 만약 당신이 얼라이언스의 이름으로 위험을 감수할 준비가 된다면, 탐사자연맹의 테일사마르 지부의 바깥에 있는 포스터를 읽어보세요."
rows["303:1692894552"]="저같은 사람이 그 나무를 벌이는 이끼에게 잡히면, 당신은 정말 용감해 여기 오게 될 겁니다.\010하프스를 방해하고 내 연쇄를 깨면 내가 네 옆에 싸워줄게\010제 시간 흐름을 늦추는 능력은 프로토베헤모스의 불구 방역을 피할 수 있게 해 줄 것입니다."
rows["303:17724443"]="생산 직업은 원료를 직접 사용할 수 있는 물건으로 바꾸거나 동료에게 줄 수 있고, 경매소에서 판매할 수 있습니다.\010종종 그들은 수집업과 결합되어 자사의 원료를 수집할 수 있지만, 단순히 경매장에서 재료를 구입할 수 있습니다."
rows["303:1784740303"]="농담이 아냐? 좋아, 겁먹지 마 다행스럽게도 당신이 가져온 부품으로 채워주면서 나도 그것에 맞춰서$B$B가방이나 은행에 다 봤어?"
rows["303:2097998924"]="다르나서스에서 남쪽으로 비행하면서 말푸리온 스톰라임을 찾아갔을 때, 아우베르딘 유적지에서 부상당한 난민들을 만났어요.$B$B그들의 원인은 옳고 나는 그들을 치유하는 데 도움을 주고 있지만 그들의 상처는 많고 시간이 걸릴 것입니다.$B$B저는 여러분도 그들에게 도움을 줄 수 있을 것이라고 믿습니다."
rows["303:210562815"]="양을 잡으면 배제도 받는데, 이건 할머니의 배제도 아니고, 꼭 써야지!$b$b몇 번  ⁇ 을 풀고 속도를 높여서 계속  ⁇ 고  ⁇ 고$b$b하지만 빨리 갈수록 더 빨리 피곤해지겠지\010"
rows["303:279052243"]="챔피언님, 환영합니다. 대 십자군 재판의 도전을 준비하기 위해 군대를 모았나요?"
rows["303:306484335"]="안젤라는 다시  ⁇ 어 사냥꾼에게 연락해$B$B지르시이는 다른 범인 사냥꾼들보다 항상 작지만, 그 일은 그를 괴롭히지 않았습니다. 아웃랜드그 모든 것을 바꿀거야, 지르'시?$B$B엄마의 작은 천사가 자라서 큰, 거칠고 치열한 범죄 사냥꾼이 될거야, 그래!"
rows["303:376924512"]="트램, 트램, 모든 사람들이 트램을 타고 가고 싶어 하는 거죠. 그 옛날의 좋은 날들은 어떻게 되었죠?  \010트램을 타고 가자... 기술공 나머지 거칠고 난만한 물건들이 있는 도시"
rows["303:518490655"]="- 놀랐어요$b$b너무 많은 질문들이 있어 무시할 수 없어$b$b왜 이 모든 무기들이 고고학적 발굴을 위해 사용되고 있습니까? 그리고 발견된 유적들은 어떻게 이루어지고 있습니까? 어떤 권위 아래서 발굴이 이루어지고 있습니까?$b$b답은 아직 나오지 않아서 직접 찾아봐야겠어"
rows["303:904770501"]="지금 웃는 거야? 도구가 있어! 그 도구에 대해 Thrall은 돈을 많이 지불했다. 당신의 플래그인을 꺼내서 읽어라! 당신이 주어진 도구를 통해 포위 엔진을 만들 수 없다면, 당신은 아무것도 만들 수 없다. 당신은 아무것도 아니다,' 벽돌 친구 타라 그리고 여기서 첫 Zeppelin를 가져가라 '당신이 나가고 있기 때문에!"
rows["304:1185647094"]="리치 왕의 붕괴를 목격했습니다. 타이탄들의 창조는 내 강력한 도끼 앞에서 떨어졌습니다. 호출되었을 때, 나는 혼자 노스렌드의 짐승에 대한 아르헨트 십자군 승리의 도끼를 이끌었습니다. 이제, 나는 궁극적인 도전을 위해 왔습니다."
rows["304:1252620415"]="그래프타가 내 창고로 돌아왔고, 내 오래된 물건들을 가지고 돌아왔고,$b$b더 좋아지고 더 강하고 더 빨리 되고 싶으면 이 미술품들은 내가 말하는 대로 할 수 있도록 보장받아"
rows["304:1437525988"]="'카드거는 자기 자신에게 미소 짓는다'$B$B아달과 그의 형제들이 나와 함께 돌아오도록 설득했지 그들의 힘만이 이 우주에서 레지옹을 몰아낼 수 있다고 믿지만$B$B어둠과 싸우려면 그들의 영원한 빛의 신호탄이 되어야 합니다."
rows["304:2114613500"]="죽은 용인 레아스트라사라는 잘 알고 있나요?$B$B레아스트라사스는 검은 용 달걀을 훔치고 정화하기 위한 계획을 세웠고, 블랙 드래곤 비행과 부패한 지구 경호인 죽음의 날개와의 유대감을 끊었습니다."
rows["304:526378359"]="이 건물의 임직원 임원장으로서, 여기서 일어나는 모든 사업, 일, 휴식, 그리고 휴식과 관련된 어느 정도 지루함을 보장하는 것이 제 의무입니다.$B$B당신이 너무 쉽고 번거롭게 할 것을 요청하는 것을 발견하면 즉시 나에게 신고하십시오."
rows["304:614289738"]="우후, 여기 가자! 모든 사람이 모든 것을 수집하고 있습니다. 그리고 지금 우리가 말하는 시리투스까지 제펠린을 통해 항공편으로 이동합니다. 마지막은 하루도 채 안 되는 시간 안에 도착해야 합니다."
rows["304:70692516"]="이 계곡의 꽃이 영원하다면 새 꽃이 자라는 것은 위험할 것 같다고 걱정하는 경우가 많아요.$B$B안전하고 작은 걸 제 부츠 아래로 치는 게 좋죠."
rows["304:748324408"]="난 너한테는 무섭게 느껴진데, 내가 너에게 가르쳐 줄 게 없다고 생각하지만 누가 할 수 있는지 알겠어? 아이언포지이제 그의 철을 아는 왜쟁이가 있습니다. 아이언포지새로운 연습생이 그를 지휘할 수 있는지 확인해"
rows["305:1159951366"]="불타는 칼의 씨가 무너진 후, 우리는 우리들, 래의 지배로부터 우리 자신과 우리 사람들을 해방시키기로 맹세했습니다.$B$B이 일은 가능하지만, 제 명예는 여전히 불만족입니다.$B$B저는 호드 내가 전투에서 영광스럽게 죽을 때까지 다른 전사들을 훈련시켜야 한다"
rows["305:1209284383"]="우린 이 벽을 터뜨려서 위크의 사람들이 새로운 항구 문과 그 밖의 도로에서 일할 수 있도록 해보고 있지만, 이 무지한 놈은 내가 너무 많은 파우더를 사용했다는 걸 비 ⁇ 고 있어!$B$B내가  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 은 이후로  ⁇ 을  ⁇ 고 있어 더 오래 걸리니까, 난 그를 운하에  ⁇ 고, 그 망할 일을 내가 끝낼거야!"
rows["305:1729015963"]="영광으로 달려가는 동안, 당신은 게임의 속도가 당신의 행동으로 돌아간다고 가정했습니다. 당신은 심지어는 저 같은 존재에게 얼마나 말도 안되는 것 같는지 짐작할 수 있습니까? 그렇게 기울이면 당신의 자신의 소소한 생각들이 당신의 두개골 안에 떠있는 땅콩 크기의 회색 물질을 꺾을 수 있습니다.\010"
rows["305:1755424296"]="내가 이 마을의 그림자 협의회 지도자니까 내 시선을 벗어나$B$B다시 만나면 마지막 사람이 될 거야$B$B아우치윈의 진막에 묻히거나, 모머에게 희생되기를 원하시겠습니까?"
rows["305:1845049324"]="밤의 형제들아 악수 ( ⁇ ) 는 너희를 부르니 너희 가죽을 뒤로 하고 너희의 형상을 그대로 받아들이고 불신자들을 멸망케 하노라"
rows["305:2050962949"]="저는 이 순례를 시작하면서 후회하기 시작했어요. 저는 그 길은 무난할 것이라고 예상했고, 여행하는 것도 낯선 것이 아니었지만, 저는 아웃랜드의 엄격함을 대비하지 못했습니다.$B$B다른 모든 것 위에, 타레리스가 내 힘을 완전히 회복하기 전에 날 여기서 밀어내고 싶어하는 것 같습니다."
rows["305:2105244687"]="이제, 우리는 시간이 좀 더 남아있는 것 같습니다. 호드는 모집 작업을 완료하고 있으며 모든 것이 실리투스까지 최종 배송을 준비하고 있습니다. 우리는 단지 얼라이언스를 기다리고 있습니다. 그들의 바보 같은 작은 대사에게 그들이 얼마나 멀리 있는지 물어보십시오."
rows["305:709003409"]="칼 자체는 어스펙트들의 자녀들과 함께 만들어져야 했습니다. 아주 드문 일이죠. 왜냐하면 용이라면 숨으로 매혹된 금속을 따뜻하게 만들고 형성해야 할 뿐만 아니라, 자신의 피를 기분을 위해 사용함으로써 자기 매혹의 분노를 억제해야 할 것입니다.\010"
rows["305:731447284"]="내 친구, 오늘 우리는 파다렌이 만난 가장 위대한 그리고 악마적인 맥주 마스터 중 한 명과 마주할 것입니다.$b$b그의 맥주의 위험성을 듣지 못한 사람은 거의 없지만 그럼에도 불구하고 그는 사람과 동물 모두를 유혹하여 그의 음료의 맛을 느낄 수 있습니다.$b$b저놈은 막아야 돼!"
rows["305:873501175"]="이 기념물은 스톰윈드의 보호 아래 쓰러진 모든 사람들에게 헌정되어 있습니다. 우리 민족은 그들의 자유를 유지하고 자신의 운명을 통제하기 위해 믿을 수 없을 만큼 많은 어려움을 겪었습니다."
rows["306:1016528517"]="네, 그 여자 위에 서있어요. 예쁜 여자예요? 바론은 얼마 전 날 캡틴으로 임명했어요. 원래는 제 것이 아니었기 때문에 이름을 붙이지 않았어요. 제 의견을 듣고 싶다면, 소년, 저는 그녀가 이름을 붙인 해병이 바다에서 너무 많은 시간을 보냈다고 생각합니다. 항구에서 충분한 시간을 보내지 않았다고 생각합니다."
rows["306:1019827957"]="그 곳에는 어떤 짐승이 살고 있는지 아세요? 최악의 일은  ⁇ 으로 여러분의 유물을 모아야 한다는 것입니다. 우리는 그 끔찍한 괴물들에 좋은 왜성들을 잃었습니다.$B$B만약 당신이 시어링 골짜기에 도달하려는 의지를 가지고 있다면 다른 방법을 찾아야 합니다."
rows["306:1060239248"]="오가나카, 정말 재능 있는 젊은 랩터이지만 가장 어려운 시험은 아직 다가오고 있습니다.$b$b트롤들은 앞의 다리를 순찰하고, 그들을 방해하기 어려울 것입니다. 하지만, 그들의 길에 두개골을 떨어뜨리면,"
rows["306:1087603526"]="이 지역은 동쪽으로 이동하여 이스트월 게이트로 들어가게 됩니다. 이 게 경비입구이자, 아우리우스 리벤데어 (Aurius Rivendare) 의 스컬지에 침투한 영토로 마지막 남은 열입니다. 우리가 그를 물리치면 스트라톨메는 다시 우리의 것이 될 것입니다."
rows["306:177206664"]=" ⁇ 리 가게에 오신 걸 환영합니다. 컷을 받으러 오세요? 색칠을 받으러 오세요?$B$B얼굴 머리카락을 꾸미고 피어싱을 할 수 있고 잉크 나이트 엘프 문신도 할 수 있고, 심지어 드레네이 뿔과 톱니도 재구조할 수 있습니다!$B$B앉으면 곧바로 일을 시작해줄게"
rows["306:1840722411"]="으으... 이 \"로켄\"이란 녀석, 아주 나쁜 놈 같군. 이제 내 이 녀석한테 신경 쓸 필요가 없어서 다행이야. 그래서... 내가 바로 이해했다면, 어떤 이유에서인지 원조 토석인이 이 정체 상태에서 벗어났고, 그때 그... 불안정환지 뭔지 때문에, 결국 지금의 드워프가 된 거지. 아니면, 드워프의 조상이 됐거나. 응?"
rows["306:228923387"]="이런 구조물들이 풍경을 비친다고 부르죠. 레지옹은 모아르그와 가나르그를 사용해서 이 이동형 동조 수용소에서 대량살상무기를 만들었어요.$B$B넌 내 눈과 무기들이 내 분노가 될 거야"
rows["306:375750460"]="이 장소의 기원이나 목적에 대해 이해할 수 없습니다.$B$B이 통로는 군대의 이동을 위해 사용되죠. 하지만 그들은 화화와 고문된 시체들로 가득 차 있습니다. 일부는 부분적으로 삼키고,$B$B우린 불지방에 있지만, 지옥의 문턱을 넘은 것 같아"
rows["306:589955955"]="시로나스는 특정 에르다르가 다른 인종을 마나리로 변화시킬 수 있는 능력을 가지고 있다고 주장한다. 드레네이는 한때 에르다르였으며 시로나스는 강력한 에르다르이다.$B$B에이전트가 웃고 있습니다.$B$B믿으실까요? 이 애도스러운 피조물은 한때 전능한 악마였죠. 어떤 바보가 그러한 힘을 거부할까요?\010"
rows["306:792811501"]="이게 그들이 할 수 있는 최선의 방법인가요?$B$B오마리온은 웃을 힘을 얻는다.$B$B켈'투자드 같은 괴물을 마주할 용기가 없어서 그의 하위군들 앞에서 무너질 거야$B$B내가 죽기 위해 여기 남겨두고 난 너같은 사람들을 옹호하는 세상에 돌아오지 않겠다\010"
rows["307:1255869800"]="곰 의 영 은 조용 하고 평화로운 시선을 가지고 당신 을 바라보고 있습니다. 곰 의 목소리 처럼 당신 에게 말 하는 소리 를 들 수 있지만, 그 생물 은 말 하는 것 을 나타내는 것 은 없습니다.$B$B나의 젊은 친구여 내가 그대에게 인도함을 구하려 왔다면 내가 그대에게 구하는 것을 구하도록 함이라"
rows["307:2144954482"]="제가 알려드리겠습니다. 당신은 분명히 우리 계급에서 서둘러 중위로 자리를 잡을 수 있다는 것을 증명하고 있습니다. 아마도 나중에 저에게 돌아올 수 있을 것입니다. 그리고 저는 당신에게 임무가 있을 것입니다."
rows["307:278103364"]="플로피 씨와 함께 산책하러 갔는데, 그 후 길을 잃었고, 정말 겁이 났어요. 왜냐하면, 그 늑대가 우리를 쫓았기 때문이죠. 하지만, 그 다음에는 이 탑을 보고, 플로피 씨와 함께 여기 숨어있었고, 늑대가 잠시 후 사라졌어요."
rows["307:335694893"]="제 친구, 저는 Kelm Hargunth입니다. 워스송 아우트라이더의 주요 공급자입니다. 당신이 워스송 골치에서 사용할 수 있는 훌륭한 상품을 제공합니다. 당신이 물건을 수리할 필요가 있다면, 저는 또한 그 서비스를 제공합니다."
rows["307:445301024"]="충분한 토큰을 가지고 있는다면 \"달의 맥주\" 클럽에 가입할 수 있습니다. 달의 맥주 클럽에 가입하는 것은 연중 브루페스트를 하는 것과 같습니다!$b$b매월 새로운 맥주 한 잔을 맛볼 수 있는 메일을 받게 됩니다. 그 맥주 한 잔을 좋아한다면 아이언포지에 있는 스톤파이어 타버너에 가서 그 곳의 판매자로부터 더 많은 것을 구입할 수 있습니다.  "
rows["307:515428199"]="전 남서쪽의 켈테릴 유적들을 탐험한 지 얼마 되지 않아서 왔어요. 그리고 지금 저는 오우프 윙 딕트에서 산맥 위에 있는 와일드킨을 조사하려고 합니다.$B$B루테라랑 마을에 있는 에레라스 앰버스키와 얘기했나?"
rows["307:791739307"]="왜 음식을 요리해야 할거야? 모든 것이 입에 먼지가 맛있는데? 언더시티 브릴 남쪽에서 언더시티 수호자 그 곳에 도착하려면 리프트를 내려가서 로데론."
rows["308:1320669085"]="챔피언들, 당신은 위대한 십자군의 재판을 물리쳤어요! 전투에서 가장 많은 모험가들이 이 재판을 완료하기를 희망할 수 있습니다. 저는 당신에게 이 추모 상자를 잘 마땅한 보상으로 제공합니다!"
rows["308:1457804659"]="다른 탐험가 를 보는 것 은 좋습니다! 어떤 사람 들 은 새로운 땅 을 발견 할 때, 즉시 요새 와 사원을 찾아 가죠.$b$b내가 아니었어$b$b한 민족의 척도를 얻기 위해서는 발을 더럽혀야 한다. 나와 함께 땅을 걷자! 이 대륙 판다레네들이 진정으로 무엇을 소중히 여기는지 보자.$b$b그것은 방황자의 길이다."
rows["308:2106850852"]="아웃랜드의 분쟁은 제가 본 전쟁보다 치명적입니다. 그리고 가장 비극적인 희생자들은 남아있는 아이들이죠.$B$B이제 스케티스 아라코아에서 샤트트라트에게 대한 위협으로, 더 많은 고아들이 돌봐야 할 것입니다. 이 아이들은 밝은 미래를 희망하지 않고 살고 있습니다."
rows["308:471430750"]="스톤메울 족속은 호드에 봉사합니다!$B$B이 협약은 오그리마, 언제 칼림도어 우리 민족의 고향으로 길러지고 있는 영웅 레크스사르가 스톤마울 오그레 족장의 지휘관을 물리쳤다.$B$B그 이후로 그들은 호드에 봉사하고 있습니다. 그리고 저는 그들을 여기에 부르고 고르도니 족속에 대한 무거운 업무를 수행합니다."
rows["309:1106098952"]="\"나는 우리가 작은 농장에서 일하고 열심히 일하지만,  ⁇ 은 그들의 정원으로 온 세계를 가지고 있다는 것을 배웠습니다. 빛 한 번만 불어오며 빛 저는 매일 학교에 다니지만, 그 똥구리는 행동으로 배운다는 것을 배웠습니다\"."
rows["309:1541467005"]="아뇨, 아뇨, 아녜요, 아뇨, 알겠습니다.$B$B하지만 넌 틀렸어 우린 그보다 더 깊은 관계를 가지고 있어$B$B게다가, 난 여기서 좋아해요."
rows["309:279866989"]="이 왕국을 통치한 지 10,000년 동안 저는  ⁇ 드라라라 가문의 경건한 땅을 걷는 사람들의 많은 흥미로운 이야기를 들었습니다.$B$B저는 이 장소로 연결되어 있어서 방문객들과 이야기를 나누는 경우가 많습니다. 여러분께 어떤 이야기가 있나요? 아니면 여러분께 어떤 이야기를 듣고 싶으십니까?"
rows["309:315792038"]="아마 뭔가...$b$b우리가 저녁을 먹자 왕의 명령을 전달했을 때 약간의 영양분이 더 많은 에너지를 줄 수 있다고 생각합니다.$b$b그리고 생각하면, 우리는 우리의 톱니에 더 많은 나무를 사용할 수 있습니다.$b$b그럼...  ⁇ ...  ⁇ , 상관없어"
rows["309:463353097"]="월 축제는 아제로스에 열리고 있다! 이 멋진 축제 에서 어르신 들 을 기리기 위해 다시 가십시오! 주요 축제는 무롱라데 에서 열릴 수 있지만, 우리는 스톰윈드, 아이언포지, 다르나서스, 썬더 블러프, 오그리마, 언더시티에서 쉽게 교통 을 제공 해 왔습니다. 우리는 그곳에서 만나기를 희망 합니다!"
rows["309:556160359"]="세비네, 알리스타르지, 그롤은 그들의 종들이 땅과 묶여있듯이 그들이 될 것이라는 것을 깨닫지 못했지만...\010"
rows["309:978228815"]="오래전, 마지막 전쟁 전에, 아버지는 노스리지 목재 공장을 운영했습니다. 그것은 그의 삶이었고 그는 그것에 헌신했습니다. 스톰윈드.$B$B스컬지의 비행과 붉은십자군의 비행은 물론 노스리지가 다시 우리의 것입니다."
rows["30:100285509"]="바텐더, 또 한 번!"
rows["30:1004107795"]="조금만 있으면 제가... 어, 어라?"
rows["30:1006666009"]="<내 복을 뚫고 다듬어라>"
