rows["30:1068003803"]="여기 있어! $p!"
rows["30:1068050363"]="수천의 얼굴을 지닌 마귀다."
rows["30:1073764251"]="숨기, 벌레 사냥이 시작됐어"
rows["30:108467800"]="같이 가자, 얘기해야 해"
