rows["30:1135587738"]="우린 그들을 통과시키지 않아야 돼!"
rows["30:1136960706"]=" ⁇ 아이가 너를 비웃고 있다"
rows["30:1141740545"]="얼굴에 맞아요"
rows["30:1142097279"]="여기서 나가, 침입자!"
