rows["30:1162578685"]="아직 한참 더 가야 하나요?"
rows["30:1165313448"]="이 어린 시절의 노력은 이제 끝납니다!"
rows["30:116807149"]="누가 이 일을 했나요?"
rows["30:1174867524"]="%s 스라임 스프레이를 발사하기 시작했어요!"
rows["30:1175843786"]="끝없는 겨울을 맞이해라."
rows["30:1178392146"]="열 받았어. 얼굴에 한 방 날린다!"
rows["30:1184942388"]="왜 내게 왔어?"
rows["30:1187749384"]="계속해, 내 콩을 마셔!"
rows["30:1189726896"]="왜 싸워야지?"
rows["30:1189878518"]="바다마는 인내심을 가지고 떠다니고 있습니다."
rows["30:1190152301"]="의무에 보고하고 있습니다, 지휘관."
rows["30:1191325149"]="그의 희생은 우리 모두를 감동시킵니다."
rows["30:119193185"]="바나나 좀 더 갖고 싶니?"
