rows["30:952921100"]="네오피트, 그만해"
rows["30:956153924"]="공사 중퇴"
rows["30:9576635"]="분노한 망자에게 안식이란 없다."
rows["30:958555615"]="아니, 로켓!"
rows["30:958953075"]="|cFF68228B나는 아래에서 왔어|r"
