rows["30:963285600"]="네놈들 모두... 비참한 고통 속에 죽으리라!"
rows["30:966210748"]="볼리온, 카리바는 아직 여기 있나요?"
rows["30:968957601"]="안개가 당신의 존재를 감지합니다!"
rows["30:969466503"]="오, 오, 오, 아!"
rows["30:969841894"]="이제 잃어버린 주문을 되찾을 시간이오!"
rows["30:971594582"]="%s sniffs 그리고 흔적을 찾습니다."
rows["30:972610524"]="%s은 호스피스 쪽으로 향한다."
rows["30:975234240"]="괜찮아... 하지만 내가 멈추지 않을거야!"
rows["30:977834368"]="배를 채울 영혼이 또 생겼구나."
