rows["30:999774447"]="커피가 남지 않았나요?"
rows["310:1215962261"]="우후, 여기 가자! 모든 사람이 모든 것을 수집하고 있습니다. 그리고 지금 우리가 말하는 시리투스까지 Zeppelin를 통해 항공으로 운반되고 있습니다. 마지막은 $2113w 일 이내에 도착해야 합니다. 모든 것이 거기에있을 때, 그리고 막대기가 집어넣은 후에는, 그 더러운 곤충에 대한 전쟁이 시작될 수 있습니다. 그들이 말하는 것처럼, '그를 배가!'\009"
rows["310:1895258357"]="안녕하세요, 저는 팅크마스터 오버스파크입니다. 현대  ⁇ 마시 공학의 건축가입니다.$b$b우리의 집회장에서는 모든 종류의 훌륭한 기계적 기적을 만들어서 당신을 찔러거나, 잘라내거나, 폭발시키거나,$b$b적어도 적들한테는 그렇지 않아요."
rows["310:235416256"]="당신 의 사안 은 정의롭고 당신 의 마음 은 진실 이 있는가? 그렇게 한다면, 동물 들 을 윤리적 으로 인간적 으로 취급 하는 드루이드 들 가운데 여기 오신 게 환영 합니다. 당신이 타락 의 어두운 길을 벗어나서 우리 를 그들의 세계 에서 공존 하도록 허용 한 동물 들 을 해치지 않는 한, D.E.H.T.A.는 당신 을 동맹자 로 간주 할 것 입니다.\010"
rows["310:331203378"]="때로는 처녀들이 토양으로 들어가서 살려고 하는데, 채소가 그들에게 비를 줄 것으로 기대하고 있습니다.$B$B스쿼터스, 할아버지가 그렇게 불렀어요. 발을 내려놓아야 해요. 말 그대로."
rows["310:831873804"]="후회합니다. 이제 제가 가진 모든 것 입니다. 한 가지 잘못된 결정으로 인해 몇 가지 끔찍한 결과가 발생했습니다. 만약 제가 그 명령을 기다렸더라면. 아마도 그들은 저 저주받은 땅에서 우리를 기다리고 있는 끔찍한 것들을 상세히 설명했을 것입니다. 어쩌면 그들은 우리를 다른 세부 사항으로 다시 안내했을 것입니다. 궁극적으로, 그것은 제 잘못이었습니다. 모든 것은 제 잘못이었습니다."
rows["311:1176908076"]="물과 혼합물들은 모두 거품과 경련이 되고, 장비 옆에 큰 톱니가 있고, 마치 톱니가 톱니가 톱니가처럼 보이는데,$B$B안전장치가 있지만 먼지가 많이 들어서고 잘 무시당해 보인다.$B$B아무 것도 만지는 건 현명하지 않다고 생각하잖아"
rows["311:1315952212"]="안녕하세요, 제 친구, 그리고 최고의 쇼에 오신 것을 환영합니다 아웃랜드!$B$B이 광대하고 신비 한 세상 에서 암흑 달 요정 이 발견 한 놀라운 일 들 을 보고 놀라십시오! 모든 연령대의 어린이 들 이 즐길 수 있는 흥미 를 가져오기 위해 우리는 어떤 비용도 절약 하지 않았습니다!"
rows["311:150572322"]="저는 그 질문에 대답할 권한이 없습니다. 하지만 저는 여러분에게 제안할 수 있습니다.$b$b브랜 브론즈베어드를 찾아라$b$b그는 이미 우리에 관하여 많은 것을 알게 되었으니 그는 다른 발견의 가장자리에 서 있나니 그를 도와 주소서 그리하면 그가 원하는 지식을 발견하게 하리라"
rows["311:1861893764"]="시체를 돌리면 죽은 오크에 칼과 마법을 씌운 흔적이 보이는데, 그녀의 무기는 거의 파괴됐고, 그녀의 머리카락은 얼굴에  ⁇ 어져 있었다.$B$B맨크릭의 설명에 따르면, 이 사람이 그의 아내라는 것은 의심의 여지가 없습니다.$B$B그는 뉴스에 화가 나겠지만 당신은 그가 진실을 알아야 한다고 확신합니다."
rows["311:2003118148"]="안녕하세요, 친구, 그리고 아제로스에서 가장 위대한 쇼에 오신 것을 환영합니다!$B$B이 광대하고 신비 한 세상 에서 암흑 달 요정 이 발견 한 놀라운 일 들 을 보고 놀라십시오! 모든 연령대의 어린이 들 이 즐길 수 있는 흥미 를 가져오기 위해 우리는 어떤 비용도 절약 하지 않았습니다!"
rows["311:316005822"]="우리는 그들을 위해 싸우고, 혹은 그들이 대표하는 것을 위해서 싸우고 있습니다.$B$B이 벽 밖에는 이 사람들의 생명이 사라지고 있습니다. 우리가 알고 있는 세상은 카엘타스, 일리던과 불타는 군단에 의해 위협받고 있습니다.$B$B이 벽들 안에서 당신은 그 세상을 위해 싸울 준비가 된 몇 명만 찾을 것입니다."
rows["311:370302161"]="나는 지금까지, 왜 다른 사람이 아닌 내가 이 특별한 장소로 보내졌는지 깊이 생각했어. 추측하건대 내 상관은 여기서 접할 수 있는 기이한 호드 문화에 금방 적응할 수 있는, 이 일에 딱 맞는 인물이 바로 나라고 생각했을 거야. 하지만 아주 악의 넘치는 소문을 들었는데, 내가 너무 말을 많이 해서 그가 날 여기로 보낸 거라더군."
rows["311:831457242"]="아하, 날 봐!$b$b새로운 상점과 완전히 새로운 상품, 그리고 거래를 당신에게 전달할 준비가 되어 있습니다!$b$b더 좋아지고 더 강하고 더 빨리 되고 싶으면 이 미술품들은 내가 말하는 대로 할 수 있도록 보장받아"
rows["311:840110861"]="이 불타는 군단악마들은 당신 얼굴 앞에 손을 보이는 것처럼 분명하게 보입니다.$B$B레지온이 돌아와 새로운 기획이 시작되는데, 정상적인 상황에서는 천발에서 악마의 존재를 감지할 수 있습니다.$B$B다른 미미스"
rows["312:111568700"]="얼라이언스의 도움으로, 제군들이 여기선 줄을 잡을 것입니다. 하지만 당신은 트랄마르에 있는 크라코크 장군에게 보고서를 전달해야 합니다. 그의 도움으로 우리는 이 악마들을 다시 그들을 낳은 격으로 몰아낼 수 있을 것입니다!"
rows["312:1181688352"]="이 벽 뒤에 얼마나 많은 지식이 숨겨져 있는지 누가 짐작할 수 있겠죠. 그리고 더 많은 것을 추가할 수 있습니다.$b$b우리 땅을 탐험하면서, 우리의 과거를 더 많이 배울 수 있는 흥미로운 물건들을 찾아보세요. 우리 역사를 충분히 정리해 보세요."
rows["312:1301510245"]="레비지는 코도처럼 미묘한데 재밌는 건 그가 명백하지 않다고 생각하는데$B$B스물 헌터 데냐이가 우릴 데리고 오지 않았으면 좋겠어 스와프라트 포스트를 설립하는 것이 그에게서 도망갈 수 있는 완벽한 기회였어"
rows["312:137040103"]="앉으면 좋겠어, 시간이 오래 걸릴 거야$B$B우리가 처음 실리투스에 도착했을 때, 세나리온 홀드의 밤 엘프들 중 첫 번째로 탐험에 합류했습니다. 우리의 일상은 평범하지 않았습니다. "
rows["312:341732747"]="벨그롬은 오그리마에서 우리를 보내서 무지한 얼라이언스에 도움을 주었지만 그의 도박이 보람을 준다면, 그것은 모든 호드의 큰 이익을 얻을 것입니다.$B$B너무 많은 오크들이 이미 죽었어, 여자들을 기쁘게 하려는 그의 욕망 때문에, 하지만 그는 여전히 우리에게 명령하고, 우리의 명예는 우리가 이 상황을 최대한 활용해야 한다고 지시한다."
rows["312:44520417"]="안녕하세요, 저는 브루머 샤도퍼의 연습생입니다.$b$B안전에 위험을 감수하면서 맛을 추구하는 그의 무분별한 노력은 수많은 부상을, 질병을 초래했고 지금은 지역의 야생동물들조차도 그의 미친 짓이 느껴지고 있습니다."
rows["312:486424718"]="믿음은 어떤 사람이 잃어 버렸지만 다른 사람은 찾았다.$B$B아니면 아마도 당신은 신앙의 의복에 대해 이야기 할 수 있습니다? 스컬지 지난 전쟁 때$B$B네, 그 대부분은 사라져... 낙스라마스의 악마들이 훔쳐갔어."
rows["313:1362744087"]="이 사건의 오그리마 오크에 대한 공격이 아니라 호드우리 존재 자체를 공격하는 것입니다!$B$B리치 왕은 두려움의 씨앗을 심으려고 노력했습니다.$B$B이...$B$B<가로쉬는 그를 둘러싸고 있는 장벽을 가리키고 있습니다.>$B$B이것은 아타스의 캠페인의 결과입니다.$B$B호드은 아무것도 두려워하지 않습니다...\010"
rows["313:1377753867"]="지렁 속에 묻혀 있는 생물은 눈에 띄지 않는 얼굴이 없는, 끔찍한 다리와 촉각들의 집합체입니다.$B$B짐승이 죽은 상태이지만, 무형 몸 주변의 물은 깨끗해 보이는데, 시체는 흥미롭게도 부패의 흔적도 보이지 않는다."
rows["313:159228336"]="원인 불명. 자료에 따르면 전쟁은 제1관리자인 로켄이 유발했다고 추정됩니다. 이 분쟁은, 남아 있던 에시르와 바니르를 로켄이 모두 제압함으로써 끝이 났습니다. 그 후 제1관리자 로켄은 지정된 관리 시설을 조작해, 토석인, 거인, 브리쿨 등 여러 원시 종족이 정체되도록 했습니다."
rows["313:1635923351"]="아이언포지 라이더들은 끈기 있는 무리가며, 그들의 방어에 크게 의존하고 있으며, 적들과의 공격으로 치를 수 있습니다.$B$B자신의 방어력을 유지하면서도, 그들의 수단을  ⁇ 고 노력하는 것은..."
rows["313:1747808502"]="언더시티 라이더들은 끈기 있는 무리가며, 그들의 방어에 크게 의존하고 있으며, 적들과의 공격으로 치를 수 있습니다.$B$B자신의 방어력을 유지하면서도, 그들의 수단을  ⁇ 고 노력하는 것은..."
rows["313:1971384357"]="몇 년 전, 저와 제 사람들은 마법사 카드가르와 paladin Turalyon를 이 세상에 따라 갔습니다. 우리의 유일한 목표는 오크와 그들의 사악한 친척들을 멸하는 것이었습니다.$B$B결국 이 어두운 세상은 찢어지고, 내 사랑하는 친구들이 공허로 사라졌습니다."
rows["313:747402485"]="우리는 마하르입니다. 당신들의 귀족들이 우리를 부르고 있는 것처럼, 우리는 마하르입니다. 마하르들은 생존자입니다.$B$B난 키로그의 아들 조린이야, 죽은자, 피가 흐르는 홀 클랜의 장군의 마지막 후손이야"
rows["313:899598950"]="데메자와 그녀의 승무원들은 해적날로 해적들의 폭동을 해놓고$B$B이제... 스팀위들 카르텔의 이 겸손한 종은 당신을 위해 무엇을 할 수 있을까요?"
rows["314:1412221054"]="브루페스트에서 모두가 즐겁게 지내길 바랍니다.$b$b이 안경은 술에 취한 사람이면 어떤 기분인지 알 수 있게 해줍니다. 하지만 음주할 때는 안경을 입으면 마치 술에 취한 것처럼 느껴집니다.$b$b두 개라도 원하시나요?"
rows["314:1670335832"]="직접 보지 못하면 믿을 수도 없을 전투! 한 상냥한 투스카르 어부가, 잔인한 바다사자 무리와 열받은 펭귄에게 온 가족을 잃고 무정한 용병으로 돌변하고 말았습니다! 이제 그를 움직이는 논리는 오로지 돈입니다! 신사 숙녀 여러분, 오리노코 터스크브레이커를 소개합니다!!"
rows["314:2024476197"]="썬더콜러에 오신 것을 환영합니다!$b$b폭발이나 그 같은 것에 대해 불평하는 사람들에게 관심을 기울이지 마세요.$b$b보아라, 만약 선장이 배를 추락시키면 이해가 되겠지 22 또는 23 하지만 그보다 더 적은 것은 언급할 가치가 없습니다."
rows["314:2053249608"]="타우렌 족장들은 내가 다음 투어를 준비하는 동안 실버문에 머물고 있어요. 그들은 연습하지 않을 때 종종 제 위에 있는 발코니에 앉아 있습니다.\010우린 현재 쇼나 팀에 고용하지 않지만 나중에 다시 확인해 볼 수 있어"
rows["314:351187842"]="물과 혼합물들은 모두 거품과 경련이 되고, 장비 옆에 큰 톱니가 있고, 마치 톱니가 톱니가 톱니가처럼 보이는데,$B$B안전장치가 있지만 먼지가 많이 들어서고 잘 무시당해 보인다.$B$B샘플을 컵에 넣는 건가요?"
rows["314:672045136"]="콘솔에 접근하면서 여러분 곁에 있는 접근 결정은 부드럽게 윙윙윙하고 빛으로 발음을 일으키기 시작합니다.$B$B정보의 급이 여러분의 마음에 흘러들어 갑자기 여러분은 관리의 에너지 생산 수준과 안정성과 다른 파이프라인으로 출력하는 것을 알게 됩니다."
rows["314:700957993"]="켈스트럼은 거창하고 자부심이 많고... 그 정도가 충분하지 않았다면...  \010전사들의 길을 따라 훈련받으려는 사람이라면 그 사람과 얘기해야 한다고 말씀드리겠습니다. 저는 그가 아이언포지의 문 동쪽의 무장실에서 찾을 수 있을 것이라고 확신합니다."
rows["314:878800463"]="엘루네의 은혜로, 테일드라시일에서 발견되는 가장 훌륭한  ⁇ 을 여러분께 드리고 싶습니다. 그리고 아마도 전 세계에서 찾을 수 있는 가장 훌륭한  ⁇ 을 드리고 싶습니다.$B$B시간 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 좀 알아보고"
rows["315:1059723318"]="우리는, 로타르의 아들들이 지금까지 여기 남아 있습니다. 싸우고, 죽고, 오늘과 같은 날이 오기를 기도하고, 포털이 열리고, 형제들이 우리를 집으로 데려오도록 기도하고 있습니다.$B$B우리가 너무 기뻐하고, 의무는 여전히 요구합니다. 우리는 이 세상을 떠나서 휴식을 취할 수 있기 전에 해야 할 일이 많습니다.\010"
rows["315:1648205200"]="당신이 원하는 것은  ⁇ 은 혐오스러운  ⁇ 이라면 스트라톨메에 당신은  ⁇ 을  ⁇ 을 것입니다.$B$B전은 라이트브라이저의 고향이었는데 지금은 켈'투자드의 하자가 몰려들었다$B$B불타는 도시의 위험함을 용기있게 해내라, 고기를 먹는 혐오스러운 것들을 쳐내라. 그들의 보상을 받아라."
rows["315:294918655"]="<만장사자]는 심심 넘치는 웃음입니다.$B$B오크가 죽기 전에 오크가 있었다, 드레네이도 죽기 전에 오크가 있었다, 하지만 네가 필연적으로 패배할 전쟁을 시작하기를 원한다면,$B$B하지만 저는 여러분의 지도자들이 이미 이 사실을 알고 있다고 생각합니다."
rows["315:49973490"]="옛날에 모가 이런 작은 함정을 세웠어요. 사람들이 이쪽으로, 그쪽으로 이동하지 못하게 하기 위해서요.$b$b마치 엄마 브램블스타프가 항상 말했듯이 \"다른 사람의 포털에 손을 넣지 마라\"."
rows["315:803575095"]="저는 롯더의 부하와 함께 싸웠고 호드 우리의 땅에서 아제로스메디프의 유산의 계승자로서, 저는 그보다 더 적게 할 수 없었습니다.$B$B마침내 이 추운 세상을 침략하고 오크들의 악을 영원히 없애는 소지가 들었을 때, 나는 친구인 투랄리온, 알레리아, 다나트, 쿠르드란과 함께 앞으로 나아갔습니다."
rows["316:1091806551"]="최근 우리 해안에서 일어난 사건에 대해 반응하는 동안 조심해야 합니다. 파우돈은 작은 맥주 도시이고 전쟁 요새가 아닙니다.$B$B여러분들이 제 백성들을 판단하는 동안도 이런 조심스러움을 가져야 한다고 여러분의 지도자들에게 권하는 것이 좋습니다.$B$B이 사건에 대해 명상해야 합니다."
rows["316:1419176693"]="스톰윈드의 벽이 강하고 높게 서 있는 것을 보는 것이 내 영혼을 좋게 만듭니다.$b$b만약 당신이 스트라톨메로 가고 싶다면, 나는 지금 당장 도움을 줄 수 없지 두려워합니다. 불타는 도시 근처의 탑은 여전히 논쟁에 있으며, 따라서 나의 힘은 당신을 도울 수 없을 정도로 약해졌습니다."
rows["316:147226513"]="네, 당신이 찾는 샤만도 봤어요. 마지막으로 봤던 건 여긴 서쪽에 있어요. 그녀는 라저만 부족 위에 언덕에 숨어 있어요. 당신이 똑똑하다면 언덕에 있는 그녀의 집까지 길을 찾을 수 있을 겁니다."
rows["316:1517327333"]="오래전 그림자 협의회는 오치윈에서 어두운 의식을 수행하려고 시도했습니다. 그들의 실패는 당신이 보는 쓰레기를 만들어 냈습니다. 쓰러진 드레네이의 뼈와 영혼이 지금 이 땅을 괴롭히고 있습니다. 나는 조상들의 무덤을 깨끗하게 하러 보내졌지만, 많은 위험에 처해 있어서 난민들을 보호하기 위해 여기 남아 있어야 합니다."
rows["316:1747506513"]="발가르드에서 그렇게 많은 사람들을 남겨두지 않아야 했지$B$B내가 그렇게 적은 군인으로 어떻게 명령을 이행할 수 있을까요?$B$B적어도 우리가 지금 당신이 여기 있는 동안 우리의 문제를 해결할 수 있는 희망이 있습니다."
rows["316:2032266730"]="너도 맹인이나 미쳤어?$B$B저는 유령입니다. 오래전부터 사라진 문명의 잔인한 기억입니다. 제가 보호하지 못한 땅에 고정되어 있습니다.$B$B오래전, 10천년 전, 난 네 몸과 뼈 같은 이 땅의 왕자이자 드래곤 라이더였어, 꿈의 이세라가 축복해줬어."
rows["316:2075306532"]="아제로스의 최고의 쇼에 오신 것을 환영합니다. 다크문 페어! 모험과 흥분은 기다리고 있습니다, 부끄러워하지 마십시오! 젊고 늙은 모두에게 신비와 상이 여기에 있습니다. 그리고 당신이 여행 중에 만난 모든 다크문 카드에 대해 교수와 이야기할 수 있도록!"
rows["316:2122836591"]="리치 왕에 대해... 알아야 하는 게 더 있네. 스컬지에 대한 지배가 없어지면 안 돼. 리치 왕을 쓰러뜨린다 해도 누군가 그 자리를 대신해야만 하네. 주인이 다스리지 않으면, 스컬지는 굶주린 메뚜기 떼처럼 이 세상을 뒤덮고 모든 생명을 파괴할 테니까."
rows["316:577133976"]="스태그헬름과 그의 군대는 실리더스에서 끝없이 쏟아져 나오는 라작스의 부대에게 완전히 압도당했습니다. 그러나 스태그헬름은 퀴라지가 단순히 성가신 정도로 여길 만한 존재가 아니었지요. 모든 나이트 엘프 전사들은 스태그헬름의 지휘 아래 하나가 되어 칼림도어를 지키기 위해 필사적으로 싸웠습니다. 그리고 그 결과 퀴라지 군대의 진군을 크게 저지할 수 있었습니다."
rows["316:747385994"]="시간의 관리인으로서 우리는 노즈도르무님의 영역을 감시하고 돌보는 일을 맡고 있습니다. 현재 주인님께서는 자리에 안 계십니다. 다시 말해 시간을 바꾸려고 시도하는 자들이 여럿 있다는 뜻이지요. 주인님께서는 필멸의 존재들 사이에 벌어지는 일에는 절대 관여하지 않으시지만 다른 이들에 의해 시간이 변경되면 시간을 바로잡으신답니다. 주인님께서는 이 문제에 대해서는 매우 보수적이랍니다."
rows["316:865521632"]="새로운 학생?$B$B- 네, 물론$B$B당신은 밝은 눈과 꼬리도 가지고 나와 함께 동부의 큰 구름 뱀을 집으로 데려가려고 생각했어요.$B$B여행은 신중하게 고려해야 합니다.$B$B쉬운 길은 아닙니다.$B$B순위는 오직 훈련이 끝날 때까지 볼 수 있는 잠재력을 가진 학생들을만 받아들인다."
rows["316:895284845"]="클라우드 뱀의 순위에서 올라가는 것보다 더 큰 영광은 없습니다.$B$B일단 자신을 증명하면 뱀을 비행하는 산으로 가지고 자유롭게 땅을 떠돌아갈 수 있습니다.$B$B또한 클라우드 뱀 승마 능력을 얻을 수 있습니다. 이는 판다리아에서 어떤 클라우드 뱀 마운트를 타는 것을 허용할 것입니다."
rows["316:932175362"]="왜 골든드래프트가 웬더브루를 알 수 있을까요?$b$b더 나쁜 건, 그 썩은 괴물이 내 딸을 쳐다보고 있을 거야$b$b만약 당신이 그를나 내 딸을 본다면, 그 분들에게도 그렇게 말할 수 있을 겁니다."
rows["317:1294108181"]="이 곳은 돈으로 만들 수 있는 가장 우수한, 최첨단 교통 수단입니다. 뭐? 딥프런 트램?  ⁇ ?"
rows["317:1299013604"]="아뇨, 그렇게 맥주를 만들죠$b$b ⁇ 은 물, 보시다시피... 작은 곤충이 들어있어요. 그 닭고기를 발효시켜주는 거죠. 어떤 사람들은 진짜 효모를 사용합니다.$b$b내 소품이잖아$b$b내가 문화가 있는 사람이 아니란 걸 알겠어"
rows["317:1338249239"]="어드벤처레이터, 화난 윈터칠의 죽음으로 적의 진전에서 잠시 멈추게 됐어요. 이 짧은 시간을 현명하게 사용하세요. 부상자를 돌보고 방어 준비를 해 주세요."
rows["317:1976125297"]="우편박스, 최근엔 쓰레기 우편만 받고 있어요!  \010이 크기를 늘려서 그 크기를 줄여서 드래곤즈의 무상 검을 빌려서  \010내가 경고하지 않았다고 말하지 마 우편 상자를 찾고 있다면,"
rows["317:1976143949"]="드래곤마우는 애너펀 캠프에서 탈출하려고 하고 이미 동쪽으로 카라반을 공격하고 있습니다. 그들은 두 명의 강력한 전사를 불러 왔습니다."
rows["318:1071474679"]="전 이올로라는 이름으로 알려져 있었는데, 이명도에서 비밀 투표가 이루어지면서 이름을 바꾸어야 했습니다.$B$B어차피, 만약 일자리를 찾고 있다면 알림판을 확인해 보세요."
rows["318:144949701"]="남쪽의  ⁇ 은 개구리와 나비 같은 작은 생물들을 먹게 될 것입니다. 우리 고릴라들은  ⁇ 을 먹게 될 것입니다. 그리고 공룡들은 고릴라를 먹게 될 것입니다. 이 모든 것은 명예롭고 자연스러운 것입니다.$b$b인간과 오크는 고릴라를 사냥하지만 그들은 피부를 잡아 몸의 부패를 남깁니다."
rows["318:817851434"]="브리즈트!$B$B보안 레벨 베타 터미널인 매트릭스 펀코그래프 3005 스트로크 B에 오신 것을 환영합니다.$B$B노란색 펀치 카드 확인됐습니다.\01001001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001"
rows["318:969129299"]="죽음의 날개의 새끼... 이세라의 자선성으로 검은 용의 비행의 후원자 죽음의 날개의 분노가 불어났다. 그들은 잠자리에 우리를 공격했습니다. 많은 사람들이 초기 파동에서 죽었지만 녹색은 우리를 보호하기 위해 일어났다.$B$B<토레스 왕자는 섬을 돌아다닐 수 있습니다>$B$B뼈는 한때 큰 용의 남은 전부였어"
rows["319:1061559436"]="결국 우리는 그 외침이 무엇으로부터 왔는지 이해했습니다. 가살꾼은 우리가 몰랐던 고통에 노출시켰습니다. 그는 우리를 수많은 실험에 사용해서 전염병을 발명하려고 시도했습니다.$B$B하루는 주로 변했으니, 그 잔인한 괴물이 우리를 마법으로 살려주지 않았더라면, 우리는 첫날 죽었을 것이다."
rows["319:1201228444"]="이 아기 들 은 찌꺼기 처럼 보일 수 있지만, 적 들 을 한 편 으로 꺾는 것 으로 달려갈 수 있습니다. 앞 램프는 전기 가전 가전 가전 가전 가전 가전 가전 가전 가전 가 가 가 가 될 수 있게 해 줍니다. $B$B심지어 탑도 공습 로켓으로 업그레이드되어 그 망할 파괴자들에 대한 확실한 우위를 갖게 되었습니다."
rows["319:1379006296"]="물론 난 찢어지는 덩어리가 없어 그건 바보같아 내가 이 저주받은 땅에서 야만족들 사이에서 걸어가고 있어요$B$B어쨌든... 내가 숨겼어.$B$B어서... 어디서 왔는지 물어봐"
rows["319:1487037788"]="저 저 망할 제이덴어 악마 중 한 명이 날 봤고, 옆구리에 좋은 찔러버렸어.$B$B더 긴급한 문제들이 있습니다. 그림자 협의회가 와일드하트 포인트에 있는 친구들을 공격하는 것을 막는 것 같은 것."
rows["319:831644708"]="만약 당신이 다크스피어의 존경을 얻고 싶다면, 필요한 사람들을 위해 귀중한 자원을 기증하는 것부터 시작해야 합니다.$B$B다양한 옷장 조각을 기부하는 대신, 그것을 기부해 주세요. 그렇게 하면 다크스피어의 인정을 받을 수 있을 것입니다."
