rows["31:950972017"]="아니, 피니, 도망치지 마!"
rows["31:953377530"]="당신을 찾아왔어요, 말푸리온"
rows["31:955917735"]="내 농작물이 성장하고 있어 이제 뭐?"
rows["31:957409513"]="정말 불꽃놀이를 하고 있나요?"
rows["31:958016400"]="아니, 내가  ⁇ 을 건지 않겠어!"
rows["31:959218725"]="난 내 검을 전투에 준비했어"
rows["31:959557038"]="잘했어, 끝내자"
rows["31:96250135"]="헬리콥터를 줘, 프리즈"
rows["31:964467143"]="끓어 넘치기 전에 넣어야 할 텐데..."
rows["31:96595018"]="반려동물을 여기 안정시키고 싶어요."
rows["31:96602548"]="%s호는 스스로 파괴되기 시작했어요!"
rows["31:96670216"]="발버둥쳐 봤자 고통만 더할 뿐..."
rows["31:970747611"]="주인님의 이름으로 처단하라!"
rows["31:971618562"]="%s는 끔찍한 웃음을 풀어줍니다."
rows["31:972581352"]="넌 말도 안 돼 마지 "
rows["31:973334669"]="라그나로스 조심해 다음이야"
rows["31:97886796"]="%s은 약화됐어요! 당장 그를 추방하세요!"
rows["31:989249011"]="멀리서 전쟁 북소리가 들립니다."
rows["31:989461726"]="난 발탈라크의 아뮬렛을 잃었어!"
rows["31:991225854"]="칩에 얽혀있어요"
rows["31:995743918"]="%s 플라즈마 폭발을 시작합니다!"
rows["31:996560668"]="내가 나쁜 짓 한 거야? 나 미안해..."
rows["320:1218957014"]="저는 얼라이언스의 미래가 판다리아와 연결되어 있다고 믿습니다.$B$B여기 착륙한 후, 우리는 특정 경로를 움직이게 했습니다. 뱀의 심장이 떨어졌을 때 우리는 그곳에 있었습니다. 어떤 의미에서, 우리는 Lorewalker Cho의 미래를 실현하는 데 도움이 되었습니다.$B$B이 때문에, 내가 일을 바로잡을 수 있도록 도와주지 않는 한 스톰윈드로 돌아갈 수 없습니다."
rows["320:1917079665"]="아마 모르겠지만, 요르문트는 숙련된  ⁇ 자일 뿐만 아니라 거대들을 죽이는 사람이기도 합니다. 왜 그는 우리가 몇 명씩 이야기를 나누는 것을 들었을까요?  \010당신은 그 대 포크 북쪽에 그의 가게에 그를 방문해야 '그대 도끼에' 그가 당신에게 이야기를 말할 수 있는지 보!"
rows["320:1929400340"]="어렸을 때 방문객이 있었어요$B$b제 남편의 신전에서 인사하러 왔나요? 그는 영웅이었죠.$B$b제 조각상들은 제가 특별히 조심스럽게 만들어서 남편에게 친근하고 보호할 수 있도록 최선을 다해 살려주죠."
rows["320:2083344829"]="부티 베이에 오신 것을 환영합니다. 파트너. 내 마을에 머무는 것은 즐겁고 무사히 좋기를 바랍니다. 후자의 중점을 두십시오. 목마른다면 많은 음료가 있고, 불안한 경우 많은 부커가 있습니다.$B$B이제... 스팀위들 카르텔의 이 겸손한 종은 당신을 위해 무엇을 할 수 있을까요?"
rows["320:360698485"]="무슨 뜻이야? 무슨 뜻이야? 그녀는 미친거야! 소녀는 우리를 향해 바로 미쳤어. 지금은 보통 나는 여자를 때리지 않지만 전 전원전에서 회복 후, 나는 꽤 damn 화가 났어요. 브랜, 럿거, 나와 원숭이 그녀의 위에 긍정적 오크가 갔다! 우리가 그녀를 방어 할 수 있었던 것은 기적입니다. 그녀는 거의 점령 된 것처럼 보였다!"
rows["320:483822949"]="아타스는 스트라톨메를 죽이고 벽 안에 있는 모든 인간을 죽이기 위해 명령을 내렸다.$B$B그는 스컬지이 그들의 속박한 전염병으로 도시를 감염시켰다는 증거를 발견했고, 이 질병은 단순히 사람들을 죽이는 것이 아닙니다.$B$B이 전염병으로 사망하는 사람들은 정신이 없는 좀비로 일어나 스컬지의 전쟁 기계를 더 발전시킵니다."
rows["320:546903310"]="스컬지 문제 가 해결 되었지만, 우리 는 끊임없이 이동 하고 먹거리를 찾고 있습니다. 그래서 저는 새로운 낚시 지점을 찾아가는 시간이라고 결정 하였습니다.$b$b바다에서 거의 한 달이 지났고, 여기까지 왔는데, 여행에 몇 개의 상자를  ⁇ 은 헤링을 챙긴 건 다행입니다."
rows["320:592325433"]="8가지 종류의 암흑달 카드들이 있습니다. 짐승, 축복, 원자, 분노, 달성, 포털, 폭풍, 전쟁주, 각 슈트에 8개의 카드, 에이스에서 8개까지 있습니다."
rows["321:1305305776"]="탐험가들의 동맹과 신장들은 매우 비슷합니다. 고고학은 우리 종교이지만, 우리는 모두 순수한 신앙에서 떨어졌습니다.\010우리의 방법은 그들이 주장하는 만큼 다르지 않습니다. 우리는 그들의 그림자 반사일 뿐입니다.\010우리처럼 만들려면 한 번만 밀어내야 돼 빛..."
rows["321:1422054330"]="이 통신사는 당신을  ⁇  모로그 아래의  ⁇ 에너의 방사선 유적지로 운반할 것입니다.$B$B걱정 마, 또 다른 건 있어 널 다시 여기로 보내줄 거야... 네, 안쪽에서 내쪽으로 돌리지 않거나 장기들을 불안정한 유기발사물로 변하지 않는다면!$B$B뭐 기다려?"
rows["321:1466856408"]="옷차림에서 손을 떼세요! 네, 네, 네, 여러분도 한 장을 원하는 걸 압니다. 모든 사람들이 내 옷차림을 원합니다. 믿으세요. 도덕적, 사회적 지위가 낮은 사람, 언젠가는 내 옷차림 판매로 부를 벌어들일 것입니다. 여기부터 아이언포지까지 모든 사람들이 바르톨로 지네스티의 이름을 알게 될 것입니다. 지네스티 라벨은 모든 사람들이 갈망할 것입니다."
rows["321:175741165"]="스톤러드에 도착했을 때 헬그럼을 제 날개 아래로 데려갔고, 내 가혹한 눈빛 아래는 그는 이전보다 더 뛰어난 추적자가 되었고, 유일한 동반자가 되었습니다.$B$B내가 강한 사람이고 고통이 내 영혼을 깨뜨릴 수 없다고 생각했는데"
rows["321:1821545996"]="이런 냉정한 환영에 놀랐을 게 없지, 우린 오랫동안 숨겼고,$b$b이 어린 나무의 주민들이 우리를 받아들이지 않든, 높은 사람이 다시 빛으로 돌아오고 있으며, 우리는 우리가 누구인지 뒤로 돌리지 않을 것입니다."
rows["321:1845707815"]="이 시간의 길은 정말 난장판입니다! 현재 우리 요원을 안에 투입해서 질서를 회복하려고 하는 중이랍니다. 얼마 되진 않지만 제가 가진 정보에 따르면 스랄의 자유가 위기에 처해 있습니다. 무한의 용군단이라는 사악한 단체가 스랄의 탈출을 막으려 하고 있습니다. 외부의 도움이 없으면 모든 게 허사가 되고 말 것입니다."
rows["321:1965702270"]="이 부분은 나중에 배웠어요. 그 당시 제가 없었기 때문이죠.$B$B펌프에 흡수를 더 높였을 때, 괴물처럼 보이는 로봇의 조각들이 나오게 되었습니다. 물론 바보들은 우리에게 말하지 않고 밤낮으로 일을 했습니다.$B$B이 때 우리는 펌프 스테이션과 통신을 잃었습니다."
rows["321:939684753"]="양양의 휘두르기를 느슨하게 하면, 그의 속도가 변하는 것을 볼 수 있습니다. 그는 걷기 시작합니다. 그는 휘두르기를 조금 더 느리게 하면, 그는 트로트하기 시작할 것입니다. 그는 트로트하는 동안 더 많은 휘두르기를 더 더 느리게 해주십시오. 그는 캔터에 들어가게 될 것입니다. 그는 캔터에있을 때 더 많은 느슨함을 더 더 더 주어 질타를 보내게 될 것입니다."
rows["322:1028857782"]="나는 위대한 도시의 아담트 아이언하르트입니다 아이언포지제 유니폼을 보면 짐작할 수 있듯이, 아이언포지 제가 마그니의 오른손이었는데, 은퇴할 때까지요. 지금은 고고학에 종사하고 있습니다. 정말 취미가구요. 그리고 세상을 보는 좋은 방법이 될 것이라고 생각했습니다."
rows["322:1196662397"]="새로운 얼굴을 보기는 좋지만, 우리는 겨우 견딜 수 있고 적도 많아요.$B$B우리를 파괴하려는 사람들, 북쪽의 사타이르, 동쪽의 나무 캠프에 있는 오크, 펠파이어 언덕의 악마들이 우리 주변에 있습니다.$B$B우리가 죽으면 이 곳을 되찾을 거야"
rows["322:1552329678"]=" ⁇ 카, 친구, 노스렌드 캠페인 참전용사 동료를 만나서 좋네요.$B$B워시프가 내게 명령해 최대의 전사들을 모아서 트와일라이트 하이랜드에 공격하라고$B$B<Warlord Krogg는 당신을 위와 아래로 보고 있습니다.>$B$B오그리마로 워시프에게 연락해 보시면 도움이 될 수 있을 것 같네요"
rows["322:1713550318"]="아제로스의 병사들이여, 그대들은 이제부터 불타는 성전에 맞서 전투를 벌이게 될 것이오. 빛을 사랑하는 모든 이들의 바람과 희망이 그대들과 함께할 것이오. 우리의 용맹한 동맹과 전우들과 함께 악마들을 물리치고 이 땅을 지켜낼 것이오. 그리하여 많은 세상을 집어삼킬 파괴적인 횡포에 종지부를 찍을 것이오."
rows["322:1735820419"]="우리는 채소를 심고 우리 채소를 토끼가 먹는다 토끼가 먹는다 늑대가 죽이고 있습니다. 우리는 고기를 가져서 늑대의 시체에서 숨기죠. 그것은 생명의 마법의 원입니다.  \010이제 켄라리온 앙클라브에 있는 테론리스에게 가서 시작해 내 직무를 다시 맡아줘"
rows["322:1765320912"]="아제로스의 병사들이여, 지금 너희는 사악한 불타는 성전과 싸우고 있다. 빛을 사랑하는 모든 이들의 희망과 기도가 너희와 함께한다. 용감한 동맹과 전우들과 함께 굳건히 버티며 악마의 공세를 꺾어라. 수많은 세계를 휩쓴 파괴의 폭정을 막아내라."
rows["322:1779400757"]="신배들한테 내가 만든 새 집이 마음에 드나요?$B$B죽음의 고통 속에서, 저는 그들 모두를 저주하고, 저만의 특별한 지하세계로 끌어들였습니다.$B$B저는 그들의 영원한 고통에 즐거워할 것이라고 생각합니다. 하지만 제가 정말로 원하는 것은 제 전 예언자에게 복수를 받는 것입니다."
rows["322:640536829"]="이 야간 검은 야간 엘프와 그들의 동맹관들의 존재에서 순종적이라고 소문되고 있어, 그녀는 더욱 가치 있는 상대가 된다. 샤두브라의 사냥 경로는 그녀를 레이인우드 피난처에서 우리의 서쪽으로 데려다, 결국 그로부터 서쪽으로 착륙한다. 그녀의 털은 피치의 색이며, 그녀의 속도는 과소평가해서는 안된다."
rows["322:849733607"]="내 사업 파트너는 사물을 죽이고, 나는 그 본질의 일부를 소실히 소실한 것, 작은 조각도 빼놓을 수 없다.$B$B하지만 계약에 대한 제 몫을 하기 위해 에테레알 크레딧으로 지불합니다.$B$B이 신용을 내가 팔아먹는 물건으로 언제든지 환불할 수 있어"
rows["323:1200051"]="조용해, 난 무르락들을 관찰하고 있어$B$B거대 거북이 껍데기 안에 사는 것은 과학을 위해 희생을 기꺼이 할 것입니다. 결국, 무르록들이 저를 여기 보시면, 그들은 내 존재에 반응하고 내 데이터를 오염시킬 것입니다!$B$B탐험가들의 리그의 첫 번째 거칠고 귀찮은 멤버로서 저는 용기있게 왜인도 전에 없었던 곳으로 갈 것입니다!"
rows["323:136492425"]="우리는 이 시간의 길에 대해 아는 것이 거의 없습니다. 사트가 파견되어 현재 저 시간의 길 내에 있지요. 그의 통신문을 통해 얻은 정보를 보면 무한의 용군단이 또다시 시간을 변형하려 하고 있다고 합니다. 어둠의 문을 연 것이 파괴를 목적으로 한 것일까요? 그렇지 않기를 기도합시다..."
rows["323:1699417639"]="우리는 하루에 한 번 이상의 암흑선을 만들 수 있었으면 좋겠지만, 그건 시간 낭비일 겁니다. 물리적으로 불가능합니다. 게다가, 우리는 그 속도로 믿을 수 없을 정도로 그것들을 만들 수도 없습니다.$B$B그리고 우리를 믿으세요, 만약 여기에 도움이 될 만큼 똑똑한 사람이 있다면, 그들은 병역에 징집될 것이고, 우리가 필요한 만큼 많은 다크크루너들을 가질 것입니다."
rows["323:379806794"]="한때는 이 동굴은 내 민족에게 신성한 곳이었는데, 그 동굴에는 사랑하는 사람들의 영혼이 있었습니다.$B$B그 시대는 오래전부터 사라졌어, 죽은 사람을 너무 깊이 돌보는 아우슈네이족은 뭔가 붙잡혔어요."
rows["324:1234380322"]="우리는  ⁇ 다라리아 트롤들이 먼 섬에서 왔어요. 왜냐하면 우리는 지금 우리 세계가 직면한 위협을 무시할 수 없기 때문입니다.$B$B우리 탐험의 지도자인 몰토르는 요자ମ୍ବା 섬으로 데려왔고, 스터글스톤의 북부 해안에서, 지금도 용감한 영웅들을 모집해 고대 트롤 도시인  ⁇ 루브에 진출하고 있습니다."
rows["324:1308627503"]="우리는 세계 곳곳에 암흑달 카드를 심어봤습니다. 어떤 가치 있는 사람이 8개의 복지의 어느 하나에 대해 완성할 수 있는지 확인하기 위해서요. 만약 당신이 그 중 한복의 8개의 카드를 모두 수집하는 데 성공한다면,"
rows["324:1361226438"]="아보레텀에 오신 것을 환영합니다.$B$B이 곳은 구름 뱀의 계급의 집입니다.$B$B여러분도 우리 편에 가입하실 수 있습니다. 하지만, 여러분은 더 많은 경험이 필요합니다.$B$B너희는 그 땅을 여행하라 그리고 너희가 힘이 될 때 내게로 돌아가라"
rows["324:1846655887"]="잠깐만요, 내가 생각했어요... 네가 내게 너무 많은 일을 해줬어, 이제 내가 너에게 대가로 작은 것을 줄 때가 됐어. 나 왔던 곳에서는 아름다운 오렌지 나무를 자란다."
rows["324:2018904387"]="협상? 협상!$B$B우리의 입장을 분명히 해드리겠습니다. 우리는 자유민족입니다. 우리가 원하는 대로 할 수 있고, 우리가 원하는 대로 올 수 있고 갈 수 있습니다.$B$B이제 드루이드에게 가서 우리가 원하는 대로 계속할 것이라고 말해주세요"
rows["324:482322402"]="금속 괴물처럼 잘했어 몇 가지 장애물이 더 있어$B$B거리의 끝에서  ⁇ 거리는 로봇을 제거하면 울두어 안에 있을 겁니다$B$B또한 거대한 불꽃이 불어오는 원동력과 녹은 거인도 눈에 띄었습니다. 하지만, 만약 여러분이 그들을 피하고 싶다면, 그들은 우리의 길을 방해하지 않습니다. "
rows["324:75432596"]="마그니 왕은 약간의 실망감을 느꼈을 것 같습니다. 그는 약간의 변화를 허용했습니다. 그는 나에게 브루페스트 Keg를 누르는 기회를 주었습니다. 나는 바구니를 효율적이고 빠르게 어떻게 열고 그 내용을 배포할 수 있는지 알아내려고 밤새도록 노력하는 것을 기억합니다. 참가자들은 모두 똑같이 빠르고 효율적으로 같은 부분을 받게 될 것입니다."
rows["324:952062152"]="한 친구와 저는 레지온주인 킬제덴과 그의 사악한 하사들의 손목에서 젊은 인간 여성을 구하러 왔습니다.$b$b우리는 카엘타스가 선웰의 깊은 곳에서 킬제덴을 불러오려고 하는 것을 발견했습니다.$b$b이 세상 때문에, 이런 일이 일어나지 않을 수 있습니다. 저는 그것이 일어나지 않는 것을 확인하려고 노력합니다."
rows["324:991329794"]="그의 논란의 여지가 있는 죽음 이후까지 로데론의 기사들과 전사들은 그들의 타락한 영웅을 기리기 위해 비슷한 스타일의 의복을 착용했다. 모그라인의 죽음은 켈'투자드에게 큰 승리로 이어졌지만, 그 결과의 순교는 전쟁이 끝날 때까지 느껴질 것이다.$B$B한 사람이 떨어지는 곳에는 많은 사람이 일어설 수 있습니다."
rows["324:996542878"]="\"순례자의 상\" 좀 더 \"무지한 바보의 미치광\"처럼$B$B수백 개의 화물 보관소에서 음식을 무료로 나눠주었습니다.$B$B하지만, 저는 제 조류 포트폴리오의 일부를 칠면조로 옮길 필요가 있다고 생각합니다."
rows["325:1027035279"]="수천 년 전, 변동 모래 전쟁이 끝나고 우리 친척들 중 세 명이 희생을 했고, 아나크로노스와 스태겔름이 아나크로노스를 닫고 있는 동안 키라지를 이 홀 안에 두었습니다.$B$B우리 각자는 스카라브 벽이 무너질 때 메리트라, 아리고스, 케일레스트라스들을 찾아갈 것을 맹세했습니다.$B$B그리고 가을이 그랬고 그래서 우리는 왔어요"
rows["325:1135646823"]="십자군 전쟁 은 고위 장군 아베디스, 고위 인키시토르 이실리언, 고고로드 모그라인 이 세력 을 형성 한 전쟁 이다. 초기 에 십자군 전쟁 은 귀족 의 순위 이었다. 지금 보시는 광신 과 광신 의 열정이 존재하지 않았다. 그랜드 십자군 전쟁 의 고리가 등장 한 후 에 부패 의 고리가 움직임을 시작 하였다."
rows["325:113739877"]="빨간 보안 카드 삽입 성공 보안 레벨 델타 데이터 카드를 배급\01000111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110"
rows["325:1606775089"]="은행이 필요한 이유는 무엇입니까? 브릴 남쪽 로데론의 유적들을 거쳐 가야 합니다. 뒤에 언더시티로 내려가는 엘리베이터들이 있습니다. 거기에 도착하면 그 나무를 짓는 혐오스러운 사람들 중 하나를 멈추고 언더시티 수호자로 전화를 걸어 더 나은 방향을 요청합니다."
rows["325:1611960851"]="인간 과 스컬지 같은 사람 들 이 알고 있는 육류 의 가장 훌륭 한 보존물 은 - 프로스트비스퍼 의 방자름물 이다. 모험가 이 를 발견 할 수 있는 한 곳 은 그 곳 에 가신 사람 은 그 곳 을 방문 하는 사람 에게도 그 물 의 이름 을 붙인 물체 이 너무 친절 하게 받아들이지 않을 것 이라고 생각 할 것 이다.$B$B하지만... 당신이 원하는 액체라면, 당신이 쫓아낼 수 있는 슐로만스라면..."
rows["326:1205663209"]="\"오로기스트\"는 무엇이라고 물으세요? 왜, 그것은 내가 모든 것을 연구한다는 것을 의미합니다! 당신은 당신이 생각할 수있는 모든 주제에 대해 당신이 알고 있거나 당신이 아는 누구보다 더 잘 알고 있습니다.$B$B샤파르의 방에서 통과하는 건 아무것도 아니었고, 그가 항상 자신의 방식으로 일을 하는 날 들어간다면, 모파리우스는 그 사람에게는 지각을 주지 않았을 것이다."
rows["326:183489645"]="전 한때 사제였지만 항상 학자였는데, 하이번으로부터 배울 기회가 엄격한 무지함을 실천하는 것보다 더 가치 있는 것 같았다.$B$B게다가 대부분의 연습생들은 3차 전쟁 때 성인이 된 젊은이들이야$B$B친구라고 부르는 사람들이 이해하기를 바랄 뿐입니다."
rows["326:2117731269"]="샤퍼는 똑똑한 놈이야 다른 에테리얼 그룹이 들어오지 않도록 입구를  ⁇ 어놨어"
rows["326:240663765"]="오래전, 필사적인 마음으로는 이해할 수 없는 우주의 차원에서, - 만약 그러한 용어를 사용할 수 있다면 -$B$B소음의 본질은 소음이라고 불리지만, 소리를 듣는 것은 영원한 죽음을 아는 것 같았다!"
rows["326:277769020"]="브루머 블랑쉬는 썬더파우 오버룩에 있을 것 같아서 폭풍이 올 거라고 확신해$b$b그 여자처럼 나는 어느 날도 될 수 없을 것 같진 않아요. 그녀는 한 번 봄바람을  ⁇ 어 버렸어요."
rows["326:599430155"]="충분한 토큰을 가지고 있는다면 \"달의 맥주\" 클럽에 가입할 수 있습니다. 달의 맥주 클럽에 가입하는 것은 연중 브루페스트를 하는 것과 같습니다!$b$b매달마다 새로운 맥주 를 맛볼 수 있는 메일을 받게 됩니다. 그 맥주 를 좋아한다면 오그리마의 스피릿 들 의 골짜기 에 있는 다크브라이어 로지 로 가서 그 곳 의 판매자 들 로부터 더 많은 것을 구입 할 수 있습니다.  "
rows["326:679438999"]="우린 조금 뒤쳐졌지만 공격은 $5071W분 안에 시작될 예정이야$B$B모든 게 준비됐고 기로콥터, 메카노 탱크와 보병이 모두 여기 있어$B$B메카토르크는 공격이 시작되기 전에 몇 가지 더 기다리고 있는 것 같습니다."
rows["327:1566939610"]="누군가가 크라운 화학 회사를 막아야 돼 내가 내 금으로 덮인 네더 로켓에 내리겠지만 그들은 차기 큰 전염병을 초콜릿이 미친 시민들의 동전으로 만들어낼거야\010만약 내가 그들의 약관에 법정 서류를 제공 할 사람을 찾아내면, 우리는 그것을 끝낼 수 있고,"
rows["327:676168468"]="저게 뭐야? 왜 내가 거기 가고 싶어?$B$B트레엘로스는 신중한 모습입니다.$B$B그래, 장갈마쉬, 우린 그 곳의 드루이드들이 왜 물수준이 떨어지는지 알아내려고 해$B$B<장관의 눈 뒤에 미친놈이 돌아다니는 걸 볼 수 있어요>$B$B우리 모두를 파괴했어! 밝은 빛!"
rows["327:728396586"]="악마들도 우리가 자신들의 천적이라는 사실을 이제 의심하지 않을 것이다. 놈들이 우리의 파멸을 바라더라도, 결국 파멸하는 것은 그들이다. 카자크와 그의 군대는 이 연합 앞에서 약해지고 패배할 것이다. 그러기 위해 우리는 몸과 마음을 모두 내던져야 한다. 놈들이 원하는 건 이 세계의 완전한 소멸이니까."
rows["327:814727621"]="탐색자 리그에 있는 우리들 중 많은 사람들이 도서관에서 남아서 우리의 발견들을 분류하고 분석합니다.$B$B브랜이 세상에 나가서 한 곳에서 다른 곳으로 이동하면서 5년 동안 그렇게 했습니다.$B$B힐다가 드디어 현장에 돌아왔고, 내가 큰 일을 할 때가 됐어!"
rows["328:1024453190"]="아센 판례는 에본 블레이드와 아르헨트 십자군에서 가장 재능있는 공예인들로 구성된 선택된 그룹입니다. 이 판례의 창작은 리치 왕와 그의 하위인들에 대한 마지막 공격을 수행하는 동안 우리 세력의 통일을 상징합니다.$b$b아센 판결의 노력으로 우리는 원시 사론이트를 우리의 의지로 굴복하는 방법을 발견했습니다."
rows["328:1413745518"]="아뇨, 아뇨, 당신은 마이든스 펀시에 타고 있습니다. 이름은 캡틴 웬크노즐입니다. 블랙워터 레이더들의 자랑스러움으로 항해할 특권을 가지고 있습니다. 블러드셀은 우리 가까이 오지 않습니다.$b$b질문이 있다면, 내가 대답해 줄게"
rows["328:23363301"]="미묘하고 어두운 지식을 가진 필사자는 아무도 능가할 수 없는 신비하고 어두운 지식을 가진 그는$B$B그의 영혼 기구로 문명 전체가 멸종되었습니다. 그와 그의 음모가 모머를 그들의 세계에 가져오게 하는 의식에 대한 기름을 위해요."
rows["328:239245218"]="내가 더 이상 화가 나게 되는 건 뭐지, 스크로티? 포세이큰그리고 우리가 지금 이 순간마다 코를 뱉고 놀리는 것을 견디지 않아도 가장 화가 나게 되는 것은 이런 망할 단복을 입고"
rows["328:370636152"]="듀르홀드 포지션 내의 배럴에 있는 불타기 폭탄을 사용해야 합니다. 5개의 폭탄이 불타고 디버전이 설정되면, 듀르홀드의 지하 감옥에서 트롤을 찾아서 그를 풀어주세요. 그를 따라가서 그가 죽지 않도록 하십시오.$B$B브레이젠은 준비되면 다른홀데로 데려다 줄 거야"
rows["328:385922794"]="엉망이 안되는데 아직 합의가 안 돼$B$B쉬어, 돈 좀 써봐요, 돈 교환자, 세탁자, 외래 음료, 낚시 트레이너까지 다 있어요.$B$B만약 누군가가 당신에게 문제가 있다면, 그냥 나에게 알려줘서 내가 처리할게.$B$B미다입니다. 보스입니다."
rows["329:1365959288"]="와임레스트 성전으로 오신 것을 환영합니다.$B$B여기 용의 비행은 그들의 존경받는 조상들의 뼈들 사이에 서로 평화롭게 협상합니다.$B$B적어도 블루 드래곤 비행기가 신전을 깜짝 공격할 때까지 우리는 평화롭게 살았습니다.$B$B우리의 축복으로 들어와, 하지만 우리는 우리의 벽 안에서 공격의  ⁇ 을 만들 수 없다는 것을 알고."
rows["329:1461519946"]="공포의 사막에서 고록록 셰일러스에서 높은 물결이 발생하면 때로는 물고기 활동이 증가하여 해안을 따라 켈프가 느슨해집니다. $b $b 개구리, 거북이 등 모든 것들이 얽혀있어요. 어쩔 수 없이 낚시만 하면$b $b  찾을 수 있는 도움이 필요하다면 알려줘"
rows["329:1702426054"]="머리가 없는 승마자는 한때 은손의 기사이자 동료 paladin들 중 영웅이 되었는데, 저주받습니다. 스카르렛 수도원 안에서 미쳤고, 그는 자신이 살아있다고 믿고 우리가 죽은다고 믿습니다.$B$B이제 그의 열정이 더 이상 빛을 섬기지 않는다. 하로우의 끝이 올 때, 그는 아제로스의 마을에 어둠과 불을 퍼뜨린다."
rows["329:249761969"]="해양 깊숙한 곳에 잠수해 본 적이 있나요? 작은 비밀을 알려드리겠습니다. 바다 깊숙한 곳에는 거품이 있는 균열이 있습니다. 물 아래에서 공기를 숨쉬는 것이 좋습니다. 이 비밀을 우리 사이에 보관해 두겠습니다.\010"
rows["329:363172250"]="기사 는 기사 의 오른손 이다. 당신 은 이미 충분히 알고 있듯이, 손 은 물건을 운반 하는 데 특히 훌륭 하 고, 따라서 당신 의 첫 번째 의무 는 제 다양한 물건, 닉크나크, 그리고 다른 다양한 장비 를 운반 하는 것 이다. 내가 땅 을 통해 정의를 배포 하는 동안. 그러한 일 등을 짊어지고는 기사 의 부적절 한 직업 이다."
rows["329:630155122"]="시로나스는 특정 에르다르가 그들의 인종의 다른 사람들을 마나리 (man'ari) 로 변화시키는 능력을 가지고 있다고 주장한다.$B$B에이전트가 웃고 있습니다.$B$B믿으실까요? 이 애도스러운 피조물은 한때 전능한 악마였죠. 어떤 바보가 그러한 힘을 거부할까요?\010"
rows["329:770362098"]="당신은 대해를 건너가야 할 것 같네요. 당신은 올바른 장소에 왔습니다. 여기 여자의 환호가 있는 가장 훌륭한 여객선입니다. 이 물들을 여행할 때, 그냥 배에 올라와 다음 당신이 알고 있는 것은 당신이 자신을 발견 할 것입니다."
rows["329:882643609"]="왜냐하면 첸 삼촌이 내게 약속해줬기 때문에!$b$b ⁇ 은 멍청하고 지루하고 게으른 늙은 삼촌일 수도 있지만 그렇다고 그를 존중하지 않겠다고 말하지 않았어$b$b게다가, 넌 혼자 잘하고 있어."
